          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"9f4325c7-1973-5c7f-9992-3686b2a85435","document_type":"judgment","category":"judicial","subcategory":"general","title":"خيانة أمانة -اختاس أموال بصفته مندوب مبيعات -ثبوت اإلدانة باإلقرار -التعزير بالسجن واجللد .","document_number":"3450816","case_number":"3474572","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/02/30","year":"1434","subject":"خيانة أمانة -اختاس أموال بصفته مندوب مبيعات -ثبوت اإلدانة باإلقرار -التعزير بالسجن واجللد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 3450816 :‬تاريخه‪1434/02/30 :‬هـ‬\n                    ‫رقم الدعوى‪3474572 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 3462390‬تاريخه‪1434/3/15 :‬هـ‬\n\n\n‫خيانــة أمانــة ‪ -‬اختــاس أمــوال بصفتــه منــدوب مبيعــات ‪ -‬ثبوت اإلدانة‬\n                                       ‫باإلقرار ‪ -‬التعزير بالســجن واجللد ‪.‬‬\n\n\n\n\n‫‪ .1‬قــول النبــي صلــى اهلل عليــه وســلم ‪ (:‬إن دماءكــم وأموالكــم عليكــم‬\n                                                                 ‫حــرام ) ‪.‬‬\n‫‪ .2‬ولقــول النبــي صلــى اهلل عليــه وســلم ‪( :‬كل املســلم علــى املســلم‬\n                                          ‫حــرام دمــه ومالــه وعرضــه) ‪.‬‬\n\n\n\n\n‫‪ -‬اتهــام املدعــي العــام للمدعــى عليــه بقيامــه بالنصــب واالحتيــال املالــي‬\n‫وخيانــة األمانــة واملجــرم شــرع ًا ويطلــب إثبــات إدانتــه مبــا أســند إليــه‬\n                        ‫واحلكــم عليــه بعقوبــة تعزيريــة تزجــره وتــردع غيــره‪.‬‬\n‫حيــث إنــه بتاريــخ ‪1433/5/4‬ه ـ تبلغــت اجلهــة األمنيــة مــن ‪ .... /‬عــن‬\n‫قيــام املدعــى عليــه بالنصــب واالحتيــال املالــي عليــه حيــث أفــاد املب ِلــغ‬\n‫أنــه يتعامــل مــع شــركة ‪ ...........‬وأن املدعــى عليــه هــو منــدوب املبيعــات‬\n‫املكلــف مــن قبلهــم وقــد اكتشــف قيامــه بعمليــات نصــب واحتيــال‬\n‫واختــاس مبالــغ ماليــة كبيــرة‪ ،‬مت حصــر مبلــغ مبدئــي منهــا قــدره‬\n‫ثالثمائــة وســتة وعشــرون ألفـ ًا وواحــد وســتون ريــا ًال ثــم بعــد ذلــك تبــن‬\n                                                                                      ‫‪18‬‬\n\f     ‫لــه أن إجمالــي املبلــغ املختلــس قرابــة أربعــة ماليــن ريــال حيــث كان‬\n     ‫املدعــى عليــه يســتلم املبالــغ نقــد ًا ويســلمه ســندات بالقبــض ثــم يوصــل‬\n     ‫هــذه الســندات إلــى شــركة ‪ ...‬ناقصــة عمــا كتــب لــه والفــرق يقــوم‬\n     ‫باختالســه طلــب املدعــي العــام إثبــات إدانــة املدعــى عليــه مبــا أســند إليــه‬\n                            ‫واحلكــم عليــه بعقوبــة تعزيريــة تزجــره وتــردع غيــره ‪.‬‬\n     ‫‪ -‬أقــر املدعــى عليــه مبــا جــاء يف الدعــوى ‪ ،‬صــدر احلكــم بثبــوت إدانــة‬\n                                                         ‫املدعــى عليــه مبــا نســب إليــه‪.‬‬\n                                                                      ‫واحلكم مبا يلي ‪:‬‬\n                                   ‫‪ -1‬بسجن املدعى عليه مدة سنتني وستة أشهر ‪.‬‬\n                       ‫‪ -2‬جلدة مائتي جلدة مفرقة على خمس دفعات متساوية‪.‬‬\n                             ‫‪ -3‬أوصى بإبعاده عن البالد بعد انتهاء محكوميته ‪.‬‬\n     ‫‪ -‬قــرر املدعــي العــام االعتــراض وطلــب االســتئناف بــدون الئحــة وقــرر‬\n           ‫املدعــى عليــه القناعــة‪ -‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد ‪ :‬ففــي هــذا اليــوم الســبت املوافــق‪1434/02/30‬‬\n     ‫ه ـ لــدي أنــا ‪ ...........‬القاضــي يف احملكمــة اجلزائيــة بحائــل وبنــاء‬\n     ‫اجلزائيــة‬\n        ‫ّ‬        ‫علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n     ‫بحائــل‪ /‬املكلــف برقــم ‪ 3474572‬وتاريــخ ‪ 1434/02/13‬ه ـ املقيــدة‬\n     ‫باحملكمــة برقــم ‪ 34369708‬وتاريــخ ‪ 1434/02/13‬ه ـ افتتحــت‬\n     ‫اجللســة الســاعة التاســعة وخمــس وأربعــن دقيقــة وفيهــا حضــر املدعــي‬\n     ‫العــام ‪ ..........‬وادعــى علــى احلاضــر معــه الســجني ‪ ..........‬لبنانــي اجلنســية‬\n\n‫‪19‬‬\n\f‫ا يف دعــواه عليــه إنــه بتاريــخ‬  ‫مبوجــب رخصــة اإلقامــة رقــم (‪ )..........‬قائـ ً‬\n‫‪ 1433/5/4‬ه ـ تبلغــت اجلهــة األمنيــة مــن ‪ ............/‬عــن قيــام املدعــى‬\n‫عليــه بالنصــب واالحتيــال املالــي عليــه حيــث أفــاد املبلــغ أنــه يتعامــل‬\n‫مــع شــركة ‪................‬وأن املدعــى عليــه هــو منــدوب املبيعــات املكلــف‬\n‫مــن قبلهــم وقــد اكتشــف قيامــه بعمليــات نصــب واحتيــال واختــاس‬\n‫مبالــغ ماليــة كبيــرة مت حصــر مبلــغ مبدئــي منهــا قــدره ثالثمائــة وســتة‬\n‫وعشــرون ألف ـ ًا وواحــد وســتون ريــال ثــم بعــد ذلــك تبــن لــه أن إجمالــي‬\n‫املبلــغ املختلــس قرابــة أربعــة ماليــن ريــال حيــث كان املدعــى عليــه‬\n‫يســتلم املبالــغ نقــد ًا ويســلمه ســندات بالقبــض ثــم يوصــل هــذه الســندات‬\n‫إلــى شــركة ‪ ...‬ناقصــة عمــا كتــب لــه والفــرق يقــوم باختالســه أوقــف‬\n‫بتاريــخ ‪ 1433/5/17‬ه ـ ثــم أفــرج عنــه بتاريــخ ‪ 1433/6/29‬ه ـ اســتناد ًا‬\n‫للمــادة (‪ )120‬مــن نظــام اإلجــراءات اجلزائيــة حيــث جــرى االتفــاق بــن‬\n‫املدعــى عليــه واملبلــغ علــى أن يســدده مبلــغ خمســمئة ألــف ريــال ثــم يتــم‬\n‫جــرد بقيــة املبالــغ املدعــى بهــا ليتــم تســليمها للمبلــغ يف مــدة ال تتجــاوز‬\n‫ســتة أشــهر حيــث تبــن أن إجمالــي املبالــغ املختلســة حســب تقريــر‬\n‫املكتــب احملاســبي مليونــن وســتمائة وخمســة وخمســن ألف ـ ًا وســتة‬\n‫وســتون ريــال والتــي أقــر املدعــى عليــه بصحتهــا إال أنــه لــم يــف مبــا مت‬\n‫االتفــاق عليــه فجــرى توقيفــه بتاريــخ ‪ 1434/1/7‬ه ـ اســتناد ًا للمادتــن‬\n‫(‪ )113.112‬مــن نظــام اإلجــراءات اجلزائيــة وباســتجوابه اعتــرف أن‬\n‫املبلــغ عميــل لديــه وأنــه يقــوم بزيــادة مبالــغ عليــه أي علــى قيمــة الفواتيــر‬\n‫حيــث إنــه ـ أي املبلــغ ـ ال يراجــع الفواتيــر وإمنــا يبنــي علــى الثقــة املتبادلــة‬\n‫بينهمــا ‪ ،‬كمــا أضــاف أنــه يقــوم بتزويــد الشــركة بصــورة مــن الســند‬\n‫يختلــف عــن الســند احلقيقــي وبإعــادة اســتجوابه أفــاد أنــه متــى مــا أثبــت‬\n\n\n                                                                                             ‫‪20‬‬\n\f     ‫املُب ّلــغ أي مبالــغ بتقريــر مــن مكتــب محاســبي أنــه مســتعد لدفعهــا ‪،‬‬\n     ‫وبتاريــخ ‪1434/1/10‬ه ـ أقــر أنــه اتفــق مــع املبلــغ علــى أن يدفــع لــه مبلــغ‬\n     ‫مليــون ريــال غيــر املبلــغ الــذي ســبق وأن دفــع لــه مقدمـ ًا وقــدره خمســمائة‬\n     ‫ألــف ريــال ويكــون باقــي املبلــغ الــذي مت النصــب واالحتيــال بــه علــى‬\n     ‫املبلــغ وقــدره مليــون ومائــة ألــف وخمســة وخمســون ألفـ ًا وســتمائة وتســعة‬\n     ‫وتســعون ريــال قــد ســامحه بــه وتنــازل عنــه وقــد أســفر التحقيــق معــه عــن‬\n     ‫اتهامــه بالنصــب واالحتيــال املالــي وخيانــة األمانــة واملجــرم شــرع ًا وذلــك‬\n     ‫لألدلــة والقرائــن التاليــة ‪ -1 :‬اعترافــه وإقراراتــه املنــوه عنهــا املدونــة‬\n     ‫علــى الصحائــف (‪ )6-1‬مــن اللفــة رقــم (‪ )19‬والصحائــف (‪ )4-1‬مــن‬\n     ‫اللفــة (‪ -2 )20‬مــا تضمنــه التقريــر املعــد مــن قبــل املكتــب احملاســبي‬\n     ‫واملصــادق عليــه مــن املدعــى عليــه املرفــق لفــة رقــم (‪ -3 )42.38‬العقــد‬\n     ‫املبــرم بــن الطرفــن املنــوه عنــه املرفــق لفــة رقــم (‪ )37‬وحيــث إن مــا‬\n     ‫أقــدم عليــه فعــل ومحــرم ومعاقــب عليــه شــرع ًا أطلــب إثبــات إدانتــه مبــا‬\n     ‫أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة تزجــره وتــردع غيــره علمـ ًا أن‬\n     ‫احلــق اخلــاص مــا زال قائمـ ًا هكــذا ادعــى املدعــي العــام وبعــرض دعــوى‬\n     ‫املدعــي العــام علــى املدعــى عليــه أجــاب مــا ذكــره املدعــي العــام يف‬\n     ‫دعــواه ضــدي مــن اتهامــي بالنصــب واالحتيــال املالــي وخيانــة األمانــة‬\n     ‫فهــذا صحيــح وذلــك أنــي كنــت اســتلم مبالــغ ماليــة لصالــح شــركة ‪...‬‬\n     ‫مــن املبلــغ وكنــت أقــوم بزيــادة الكشــوفات احلســابية علــى املبالــغ التــي‬\n     ‫لصالــح الشــركة وهــي يف الواقــع ليســت مســتحقة علــى املبلــغ ‪.........‬ثــم‬\n     ‫أقــوم باختالســها وكان مجمــوع املبالــغ التــي اختلســتها مــن املبلــغ بهــذه‬\n     ‫الطريقــة‪ ...............‬مليــون وخمســمئة ألــف ريــال تقريبــا هكــذا أجــاب‬\n     ‫فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وملصادقــة املدعــى عليــه علــى‬\n\n\n‫‪21‬‬\n\f‫الدعــوى العامــة ولعمــوم قــول النبــي صلــى اهلل عليــه وســلم‪ (:‬إن دمائكم‬\n‫وأموالكــم عليكــم حــرام) ولقــول النبــي صلــى اهلل عليــه وســلم‪(:‬كل‬\n‫املســلم علــى املســلم حــرام دمــه ومالــه وعرضــه) ملــا تقــدم كلــه فقــد‬\n‫ثبــت لــدي قيــام املدعــى عليــه بالنصــب واالحتيــال املالــي علــى املواطــن‬\n‫‪.......‬وحكمــت بســجن املدعــى عليــه مــدة ســنتني وســتة أشــهر وجلــدة‬\n‫مائتــي جلــدة مفرقــة علــى خمــس دفعــات متســاوية وأوصيــت بإبعــاده‬\n‫عــن البــاد بعــد انتهــاء محكوميتــه هــذا مــا ظهــر لــي وبــه حكمــت‬\n‫واهلل أعلــم واحكــم وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه‬\n‫القناعــة بهــذا احلكــم ولــم يقنــع املدعــي العــام بهــذا احلكــم وطلــب‬\n‫رفعــه حملكمــة االســتئناف بــدون الئحــة اعتراضيــة وبهــذا انتهــت هــذه‬\n‫القضيــة يف متــام الســاعة العاشــرة والثلــث وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/02/30‬هـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n‫األولــى املختصــة بتدقيــق القضايــا اجلزائيــة مبحكمــة االســتئناف‬\n‫مبنطقــة حائــل علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بحائــل ‪34369708‬يف تاريــخ ‪1434/3/7‬ه ـ واملقيــدة لدينــا‬\n‫برقــم ‪ 34605438‬يف تاريــخ ‪1434/3/9‬ه ـ املرفــق بهــا القــرار الشــرعي‬\n‫الصــادر مــن صاحــب الفضيلــة الشــيخ‪ ............./‬القاضــي باحملكمــة‬\n‫اجلزائيــة بحائــل برقــم‪ 3450816/‬يف تاريــخ ‪1434/2/30‬ه ـ اخلــاص‬\n‫بدعــوى املدعــي العــام ضــد‪............ /‬لبنانــي اجلنســية مبوجــب رخصــة‬\n‫اإلقامــة رقم‪)........(/‬بشــأن نصــب واحتيــال وقــد تضمــن القــرار حكــم‬\n‫صاحــب الفضيلــة وفقــه اهلل علــى املدعــى عليــه علــى النحــو املفصــل يف‬\n‫القــرار املرفــق وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة جــرت‬\n\n\n                                                                                   ‫‪22‬‬\n\f     ‫املصادقــة علــى ماحكــم بــه فضيلتــه وفقــه اهلل بالقــرار املشــار إليــه ‪.‬‬\n     ‫واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪23‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"41499c81-d627-5952-8b7f-c01b2e788165","source_page_start":18,"source_page_end":23,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"2baad1dbeb85f420026198f883b011e34dcdc35dfdeea7ab4c73aff6e4840dd8","normalized_text_hash":"e4b7b712ae78e7825c0aff292656863201325d4c23db702f031c3969db1442f2","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v27-p18-3450816"},{"id":"068f0a7d-1241-563a-b7fe-a109b97145cd","document_type":"judgment","category":"judicial","subcategory":"general","title":"خيانة أمانة -االستيالء على ملفات ومستندات ملشاريع مؤسسة من قبل موظف يعمل بها وإخفائها بقصد اإلضرار واملساومة على إرجاعها -إنكار الدعوى -إجراءات االستدالل -التعزير بالسجن واجللد للحقن العام واخلاص .","document_number":"344014","case_number":"33351384","judgment_number":null,"decision_number":null,"circular_number":null,"court":null,"circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/6","year":"1434","subject":"خيانة أمانة -االستيالء على ملفات ومستندات ملشاريع مؤسسة من قبل موظف يعمل بها وإخفائها بقصد اإلضرار واملساومة على إرجاعها -إنكار الدعوى -إجراءات االستدالل -التعزير بالسجن واجللد للحقن العام واخلاص .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"    ‫رقم الصك‪ 344014:‬تاريخه‪1434/1/6 :‬هـ‬\n                    ‫رقم الدعوى‪33351384 :‬‬\n       ‫قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34220846‬تاريخه‪1434/5/25 :‬هـ‬\n\n\n‫خيانــة أمانــة ‪ -‬االســتيالء علــى ملفــات ومســتندات ملشــاريع مؤسســة‬\n‫مــن قبــل موظــف يعمــل بهــا وإخفائهــا بقصــد اإلضــرار واملســاومة علــى‬\n‫إرجاعهــا ‪ -‬إنــكار الدعــوى ‪ -‬إجــراءات االســتدالل ‪ -‬التعزيــر بالســجن‬\n                                       ‫واجللــد للحقــن العــام واخلــاص ‪.‬‬\n\n\n\n\n‫‪ -‬قولــه تعالــى (( يــا أيهــا الذيــن آمنــوا ال تخونــوا اهلل والرســول وتخونوا‬\n                                                  ‫أماناتكــم وأنتــم تعلمون ))‬\n‫‪ -‬قولــه عليــه الصــاة والســام ( املســلم مــن ســلم املســلمون مــن لســانه‬\n                                                                          ‫ويــده)‪.‬‬\n\n\n\n\n‫أســفر التحقيــق عــن توجيــه االتهــام للمدعــى عليــه بخيانــة األمانــة‬\n‫باالســتيالء علــى ملفــات ومســتندات ملشــاريع املؤسســة وإخفائهــا بقصــد‬\n‫اإلضــرار واملســاومة علــى إرجاعهــا‪ ،‬وذلــك بعــد مــا مت القبــض علــى‬\n‫املدعــى عليــه مــن قبــل اجلهــات املختصــة بنــاء علــى بــاغ املديــر العــام‬\n‫ألحد املؤسســات املتضمن أن املدعى عليه حضر إلى مكتب املؤسســة‬\n‫وســرق مســتندات وملفــات عائــدة للمؤسســة تتعلــق مبشــاريع تقــدر مببلغ‬\n‫عشــرة ماليــن ريــال‪ ،‬كمــا أفــاد بقيــام املوظــف (املدعى عليه) بإرســال‬\n\n                                                                                     ‫‪24‬‬\n\f     ‫رســالة جلوالــه نصها(خلــص إلــي عنــدك أســلمك اللــي عنــدي) وأفــاد‬\n     ‫بوجــود امللفــات مبنــزل املدعــى عليــه ويرغــب يف اســتعادتها ‪ -‬باالطــاع‬\n     ‫علــى صحيفــة حالتــه اجلنائيــة لــم يعثــر لــه علــى ســوابق ‪ -‬طلــب املدعــي‬\n     ‫العــام إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة ‪ -‬بعــرض‬\n     ‫دعــوى املدعــي العــام علــى املدعــى عليــه أنكرهــا جملــة وتفصيــا‪،‬‬\n     ‫ودفــع بــأن لــه مســتحقات ماليــة لــدى املؤسســة وعندمــا طالبهــم بهــا مت‬\n     ‫تلفيــق هــذه التهمــة ضــده وأمــا األوراق واملســتندات التــي عثــر عليهــا يف‬\n     ‫ســكنه اخلاص فهي عائدة للمؤسســة وملشــاريع قدمية مت االنتهاء منها‪،‬‬\n     ‫وليــس لهــا أي قيمــة وهــي أيضــا صــور وليســت أصــول‪ ،‬وأمــا الرســالة‬\n     ‫التــي أشــار إليهــا املدعــي العــام فقــد كان يقصــد الســيارة املســلمة لــه‬\n     ‫مــن قبــل الشــركة ثــم إنــه يف اليــوم التالــي قــام بتســليم الســيارة خشــية‬\n     ‫الوقــوع يف أي مســاءلة نظاميــة ‪ -‬مت ســماع شــهادة الشــهود‪ ،‬وتعديلهــم‪-‬‬\n     ‫حضــر املدعــي باحلــق اخلــاص وادعــى علــى املدعــى عليــه مبثــل دعــوى‬\n     ‫املدعــي العــام وطلــب تعزيــره ‪ -‬أحضــر املدعــي باحلــق اخلــاص شــهودا‪،‬‬\n     ‫ومت ســماع شــهادتهم‪ -‬جــرى االطــاع علــى محضــر القبــض كمــا جــرى‬\n     ‫االطــاع علــى أقــوال املدعــى املدونــة علــى ملــف إجــراءات االســتدالل‬\n     ‫‪ -‬بنــاء علــى مــا تضمنتــه شــهادة الشــهود املعدلــن ومــا تضمنــه محضــر‬\n     ‫القبــض وإقــرار املدعــى عليــه بــأن جميــع املســتندات عائــدة للمؤسســة‬\n     ‫ا‬\n     ‫وأنهــا موجــودة يف منزلــه‪ ،‬وألن مــا أقــدم عليــه املدعــى عليــه يعــد عمـ ً‬\n     ‫ا قبيحــا وليــس مــن األمانــة‪ ،‬وألن مــا دفــع بــه املدعــى عليــه‬ ‫محرمـ ًا وفعـ ً‬\n     ‫يعــد دفعـ ًا غيــر مقبــول لــذا ثبتــت إدانــة املدعــى عليــه بخيانــة األمانــة مــن‬\n     ‫خــال االســتيالء علــى ملفــات ومســتندات ملشــاريع املؤسســة وإخفائهــا‬\n     ‫بقصد اإلضرار واملســاومة على إرجاعها ومت احلكم بتعزيره بالســجن‬\n\n\n‫‪25‬‬\n\f‫مــدة ثمانيــة أشــهر وجلــده خمس ـ ًا وثالثــن جلــدة مكــررة أربــع مــرات‬\n‫وذلــك للحقــن العــام واخلــاص مناصفــة بينهمــا ســجن ًا وجلــد ًا ‪ -‬بعــرض‬\n‫احلكــم علــى املدعــي العــام واملدعــي باحلــق اخلــاص واملدعــى عليــه قــرر‬\n‫املدعــي باحلــق اخلــاص القناعــة وقــرر املدعــى عليــه عــدم قناعتــه باحلكــم‬\n‫وطلــب تقــدمي الئحتــه االعتراضيــة ولــم يبــد املدعــي العــام اعتراضــه‪،‬‬\n           ‫وبعــد رفــع احلكــم حملكمــة االســتئناف متــت املصادقــة عليــه ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة يف محافظــة جدة‪/‬املســاعد برقــم ‪33351384‬‬\n‫وتاريــخ ‪1433/05/22‬ه ـ املقيــدة باحملكمــة برقــم ‪ 33948886‬وتاريــخ‬\n‫‪1433/05/19‬ه ـ ففــي يــوم الثالثــاء املوافــق ‪1433/05/25‬ه ـ افتتحت‬\n‫اجللســة الســاعة ‪ 08 : 19‬وفيهــا حضــر املدعــي العــام ‪.....‬بالنيابــة عــن‬\n‫املدعــي العــام ‪.....‬بالتعميــد ‪ .....‬يف ‪1433/01/16‬ه ـ وادعــى علــى ‪.....‬‬\n‫عام ـ ًا ســوري اجلنســية مبوجــب رخصــة إقامــة رقــم (‪ ).....‬موقــوف‬\n‫بســجون محافظــة جــدة مبوجــب أمــر متديــد التوقيــف رقــم (‪ ).....‬وتاريــخ‬\n‫‪1433/3/22‬ه ـ اســتناد ًا للمــادة رقــم (‪ )108‬مــن نظــام اإلجــراءات‬\n‫اجلزائيــة بتاريــخ ‪1433/3/7‬ه ـ مت القبــض علــى املدعــى عليــه مــن قبــل‬\n‫شــعبة التحريــات والبحــث اجلنائــي بشــرطة محافظــة جــدة بحــي ‪.....‬‬\n‫ـاء علــى بــاغ املدعــي‪ ...../‬املديــر العــام ملؤسســة ‪.....‬املتضمــن أن‬\n                                                                         ‫بنـ ً‬\n‫املدعــى عليــه حضــر إلــى مكتــب املؤسســة التابعــة لــه وســرق مســتندات‬\n\n\n                                                                                    ‫‪26‬‬\n\f     ‫وملفــات عائــدة للمؤسســة تتعلــق مبشــاريع تقــدر مببلغ(‪)10‬مليــون ريــال‬\n     ‫كمــا أفــاد بقيــام املوظــف بإرســال رســالة جلوالــه نصهــا (خلــص إلــي‬\n     ‫عنــدك أســلمك اللــي عنــدي) كمــا أفــاد بوجــود ملفــات مبنــزل املدعــى‬\n     ‫عليــه ويرغــب يف اســتعادتها وبتاريــخ ‪1433/3/7‬ه ـ مت االنتقــال رفــق‬\n     ‫املدعــى عليــه إلــى منزلــه وبتفتيشــه عثــر علــى العديــد مــن امللفــات‬\n     ‫وأجهــزة ألب تــوب واملوضحــة جميعهــا مبلــف التحقيــق املرفــق باللفــة‬\n     ‫(‪ )19‬واملدونــة بالصفحــات (‪ )12-3‬كمــا عثــر علــى شــهادات عائــدة‬\n     ‫للمدعــى عليــه معــدل فيهــا املهنــة مــن مســاعد مهنــدس إلــى مهنــدس‬\n     ‫مدنــي بواســطة الفوتوشــوب وباســتجواب املدعــى عليــه أقــر بــأن جميــع‬\n     ‫املضبوطــات التــي عثــر عليهــا مبنزلــه عائــدة ملؤسســة ‪.....‬وقــد أخذهــا‬\n     ‫مــن املؤسســة بنفســه كمــا أقــر بقيامــة بإرســال الرســالة املنــوه عنهــا‬\n     ‫ملديــر املؤسســة وأن قصــده مــن ذلــك هــو الضغــط عليــه الســتالم حقوقــه‬\n     ‫‪.‬كمــا أقــر بتعديــل مهنتــه يف الشــهادات اخلاصــة بــه وذلــك عــن طريــق‬\n     ‫الفوتوشــوب وســحبها بعــد ذلــك عــن طريــق الكمبيوتــر وقــد فــرزت لــه‬\n     ‫أوراق بشــأن ذلــك وأحيلــت إلــى شــعبة التزويــر باخلطــاب رقم‪.....‬وتاريــخ‬\n     ‫‪1433/4/23‬ه ـ وأســفر التحقيــق عــن توجيــه االتهــام للمدعــى عليــه‬\n     ‫بخيانــة األمانــة مــن خــال االســتيالء علــى ملفــات ومســتندات ملشــاريع‬\n     ‫املؤسســة وإخفائهــا بقصــد اإلضــرار واملســاومة علــى إرجاعهــا ‪.‬وذلــك‬\n                                                            ‫لألدلــة والقرائــن التاليــة‪-:‬‬\n                        ‫‪ .1‬ما ورد يف إقراره املنوه عنه املدون ص (‪ )13‬لفة (‪)19‬‬\n      ‫‪ .2‬ما ورد يف محضر االنتقال واملعاينة املنوه عنه ص(‪ )12-3‬لفه (‪)19‬‬\n             ‫‪ .3‬ما ورد يف محضر تفريغ الرسالة املنوه عنها ص (‪ )6‬لفه (‪)18‬‬\n     ‫وباالطــاع علــى صحيفــة حالتــه اجلنائيــة لــم يعثــر لــه علــى ســوابق وحيــث‬\n\n\n‫‪27‬‬\n\f‫أن مــا أقــدم عليــه املدعــى عليــه وهــو بكامــل أهليتــه املعتبــرة فعــل محرم‬\n‫ومعاقــب عليــه شــرع ًا لــذا اطلــب إثبــات مــا اســند إليــه واحلكــم عليــه‬\n‫بعقوبــة تعزيريــه لقــاء ذلــك (علم ـ ًا أن احلــق اخلــاص لــم ينتهــي ) وأســاله‬\n            ‫اجلــواب وصلــى اهلل علــى نبينــا محمــد حــرر يف ‪1433/5/25‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم الثالثــاء ‪1433/05/25‬ه ـ‬\n‫افتتحــت اجللســة الســاعة الثامنــة والنصــف وفيهــا حضــر املدعــى عليــه‬\n‫ا مــا ذكــره املدعــي العــام‬  ‫وبســؤاله عــن دعــوى املدعــي العــام أجــاب قائـ ً‬\n‫ا ومــا حصــل هــو أن لــي مســتحقات ماليــة‬        ‫غيــر صحيــح جملــة وتفصيـ ً‬\n‫لــدى مؤسســة ‪.....‬وعندمــا طالبــت بهــا مت تلفيــق هــذه التهمــة ضــدي وأمــا‬\n‫األوراق واملســتندات التــي عثــر عليهــا يف ســكني اخلــاص فهــي عائــدة‬\n‫للمؤسســة وملشــاريع قدميــة مت االنتهــاء منهــا ومت تقفيلهــا وليــس لهــا‬\n‫أي قيمــة وهــي أيضــا صــور وليســت أصــول فكيــف أقــوم بســرقتها أو‬\n‫أســاوم عليهــا وأمــا الرســالة التــي أشــار إليهــا املدعــي العــام فقــد كنــت‬\n‫أقصــد الســيارة املســلمة لــي مــن قبــل الشــركة ثــم إنــي يف اليــوم التالــي‬\n‫قمــت بتســليم الســيارة خشــية الوقــوع يف أي مســاءلة نظاميــة هكــذا‬\n‫ا نعــم‬‫أجــاب وبســؤال املدعــي العــام عــن بينتــه طبــق دعــواه أجــاب قائ ـ ً‬\n‫لــدي بينــة وأطلــب إمهالــي إلحضارهــا هكــذا أجــاب وعليــه جــرى رفــع‬\n‫اجللســة وبــاهلل التوفيــق وكان ختــام اجللســة الســاعة التاســعة حــرر‬\n‫يف ‪1433/05/25‬ه ـ احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم األربعــاء‬\n‫املوافــق ‪1433/06/11‬ه ـ افتتحــت اجللســة الســاعة العاشــرة وفيهــا‬\n‫حضــر للشــهادة وأدائهــا كل مــن (‪..... )1‬ســعودي بالهويــة رقــم ( ‪).....‬‬\n‫(‪..... )2‬ســعودي بالهويــة رقــم ( ‪ ).....‬وباستشــهادهما شــهدا هلل تعالــى‬\n‫ـاء يــوم االثنــن‬\n                 ‫قائلــن أنــه جــرى االنتقــال يف متــام الســاعة الثامنــة مسـ ً‬\n\n                                                                                       ‫‪28‬‬\n\f     ‫املوافــق ‪1433/03/07‬ه ـ وبرفقــة الســجني ‪..... /‬ســوري اجلنســية إلــى‬\n     ‫منزلــه وعنــد الوصــول إلــى املنــزل اتضــح بأنــه يقــع بحــي ‪.....‬وهــو عبــارة‬\n     ‫عــن شــقة مكونــة مــن غرفتــن وصالــة ومطبــخ وحمــام ومت فتــح البــاب‬\n     ‫اخلارجــي للشــقة مــن قبــل الســجني وجــرى دخــول الغرفــة اخلاصــة بــه ومت‬\n     ‫فتحهــا مــن قبلــه وعثــر بداخــل الغرفــة علــى أوراق ومســتندات يقــدر‬\n     ‫عددهــا ب ( ‪ ) 133‬مائــة وثالثــة وثالثــون ملــف ومســتند أشــير إليهــا‬\n     ‫يف امللــف رقــم (‪ )19‬ص (‪ )11-3‬املرفــق باملعاملــة هــذا مــا لدينــا ونشــهد‬\n     ‫بــه ثــم حضــر املدعــي باحلــق اخلــاص ‪ .....‬بالســجل املدنــي رقــم ( ‪).....‬‬\n     ‫ا إن املدعــى عليــه قــام بخيانــة األمانــة حيــث أنــه أخــذ أوراق‬\n                                                                         ‫وادعــى قائـ ً‬\n     ‫ومســتندات وملفــات ملشــاريع املؤسســة وقــام بإخفائهــا بقصــد اإلضــرار‬\n     ‫باملؤسســة وبــدون وجــه حــق وبقصــد املســاومة وقــد تضــررت مــن هــذا‬\n     ‫الفعــل أطلــب تعزيــر املدعــى عليــه بعقوبــة تعزيريــه رادعــة هــذه دعــواي‬\n     ‫وحيــث لــم يحضــر املدعــى عليــه جــرى رفــع اجللســة إلحضــاره وعــرض‬\n     ‫الشــهادة يف دعــوى املدعــي العــام عليــه وبــاهلل التوفيــق وكان ختــام‬\n     ‫اجللســة الســاعة العاشــرة والنصــف وصلــى اهلل علــى نبينــا محمــد حــرر‬\n     ‫يف ‪1433/06/11‬ه ـ احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم األربعــاء‬\n     ‫افتتحــت اجللســة وفيهــا حضــر لتزكيــة الشــهود أعــاه كل مــن (‪)1‬‬\n     ‫‪.....‬ســعودي بالســجل رقــم (‪.......... )2( ).....‬ســعودي بالســجل رقــم (‬\n     ‫‪ ).....‬وشــهد بعدالــة الشــاهدين وإنهمــا مقبولــي الشــهادة لهمــا وعليهمــا‬\n     ‫وهمــا مــن أهــل التقــوى والصــاح وصلــى اهلل علــى نبينــا محمــد حــرر يف‬\n                                                                     ‫‪1433/06/11‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم االثنــن املوافــق ‪1433/07/21‬هـ‬\n     ‫افتتحــت اجللســة وفيهــا حضــر املدعــى عليــه ‪.....‬وبعــرض الشــهادة عليــه‬\n\n\n‫‪29‬‬\n\f‫ا مــا جــاء يف الشــهادة صحيــح إال أن هــذه األصــول والصــور‬   ‫أجــاب قائـ ً‬\n‫تعــود لــي حيــث إنــي مســؤول قســم اجلــودة والســامة والتســعيرة يف‬\n‫الشــركة فهــذه األصــول أنــا الــذي عملتهــا للشــركة حيــث إن املديــر‬\n‫يصــر علـ ّـي أن أعمــل يف املنــزل أعمــال إضافيــة هكــذا أجــاب وألجــل‬\n‫حضــور املدعــي باحلــق اخلــاص وإحضــار زيــادة بينــة جــرى رفــع اجللســة‬\n                 ‫وصلــى اهلل علــى نبينــا محمــد حــرر يف ‪1433/07/21‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة يف محافظــة جــدة‪ /‬املســاعد برقــم ‪33351384‬‬\n‫وتاريــخ ‪1433/05/22‬ه ـ املقيــدة باحملكمــة برقــم ‪33948886‬‬\n‫وتاريــخ ‪1433/05/19‬ه ـ ففــي يــوم االثنــن املوافق‪1433/10/23‬ه ـ‬\n‫افتتحــت اجللســة الســاعة وفيهــا حضــر املدعــي باحلــق اخلــاص واملدعــى‬\n‫ا مــا‬\n     ‫عليــه وبســؤال املدعــى عليــه عــن دعــوى املدعــي اخلــاص أجــاب قائـ ً‬\n‫ذكــره املدعــي صحيــح ولكــن املســتندات التــي بحوزتــي كلهــا صــور‬\n‫وقــد اســتلمتها منــي قســم شــرطة ‪.....‬وكمــا أنهــم قامــوا بأخــذ أغــراض‬\n‫اخلاصــة لــي وهــي عبــارة عــن أجهــزة جــوال وحواســيب ولــم يردوهــا‬\n‫لــي هكــذا أجــاب وألجــل طلــب البينــة مــن املدعــي اخلــاص جــرى‬\n‫رفــع اجللســة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                              ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1433/10/23‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم االثنــن املوافــق ‪1433/11/1‬ه ـ‬\n‫افتتحــت اجللســة وفيهــا حضــر املدعــي باحلــق اخلــاص وحضــر حلضــوره‬\n‫املدعــى عليــه وبســؤال املدعــي باحلــق اخلــاص عــن بينتــه التــي طلــب‬\n‫ا لقــد أحضــرت بينتــي وأطلــب ســماع مــا‬ ‫إمهالــه إلحضارهــا أجــاب قائـ ً‬\n\n\n                                                                                    ‫‪30‬‬\n\f     ‫لديهمــا مــن شــهادة وقــد حضــر الشــاهد‪..... /‬ســوداني اجلنســية باإلقامــة‬\n     ‫ا أشــهد هلل بــأن املهنــدس‪..... /‬كان مســئول‬        ‫رقــم ( ‪ ).....‬وشــهد قائ ـ ً‬\n     ‫عــن قســم ضبــط اجلــودة يقــوم بتســليم األوراق لالستشــاري وكذلــك‬\n     ‫إحضــار بعــض األوراق مــن االستشــاري وتســليمها للشــركة وأن األوراق‬\n     ‫التــي وجــدت مبنزلــه ال علــم لــي بهــا هكــذا شــهد ثــم حضــر للشــهادة‪/‬‬\n     ‫‪.....‬مصــري اجلنســية باإلقامــة ( ‪ ).....‬وشــهد بقولــه أشــهد هلل تعالــى بأنــي‬\n     ‫أعمــل لــدى شــركة ‪.....‬للمقــاوالت يف طريــق املدينــة املنــورة ولــي فتــرة‬\n     ‫ثــاث ســنوات وســلمت لــي ســيارة لتوصيــل املــدارس وأننــي رأيــت املدعى‬\n     ‫عليــه قــد أخــذ ملفــات مــن الشــركة وأعادهــا بعــد ثــاث ســاعات هــذا‬\n     ‫ا إننــي‬\n            ‫مــا لــدى وبــه أشــهد وبعــرض ذلــك علــى املدعــى عليــه أجــاب قائـ ً‬\n     ‫أكتفــي بإجابتــي الســابقة هكــذا أجــاب وبســؤال املدعــي باحلق اخلاص‬\n     ‫ا ليــس لــدي زيــادة بينــة هكــذا‬    ‫إن كان لديــه زيــادة بينــة أجــاب قائ ـ ً‬\n     ‫أجــاب وألجــل تأمــل القضية جرى رفع اجللســة حــرر يف ‪1433/11/01‬هـ‬\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة اجلزائيــة‬\n     ‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n     ‫احملكمــة اجلزائيــة يف محافظــة جدة‪/‬املســاعد برقــم ‪33351384‬‬\n     ‫وتاريــخ ‪1433/05/22‬ه ـ املقيــدة باحملكمــة برقــم ‪ 33948886‬وتاريــخ‬\n     ‫‪1433/05/19‬ه ـ ففــي يــوم األحــد املوافق‪1433/12/26‬ه ـ افتتحــت‬\n     ‫اجللســة الســاعة وفيهــا حضــر املدعــى عليــه ‪ .....‬واملدعــي باحلــق اخلــاص‬\n     ‫‪ .....‬واملدعــي العــام هــذا وقــد جــرى منــا االطــاع علــى أوراق املعاملــة‬\n     ‫ومنهــا محضــر القبــض املرفــق لفــة رقــم(‪ )19‬وهــو مطابــق ملــا ذكــره‬\n     ‫املدعــي العــام كمــا جــرى االطــاع علــى أقــوال املدعــى عليــه املدونــة‬\n     ‫علــى ملــف إجــراءات االســتالل املرفــق لفــة رقــم (‪ 19‬ص‪ )2‬ويتضمــن‬\n\n\n‫‪31‬‬\n\f‫إقــراره بــأن جميــع املســتندات عائدة ملؤسســة ‪.....‬وأنهــا موجودة يف منزله‬\n‫فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ومــا تضمنتــه شــهادة الشــهود‬\n‫املعدلــن ومــا تضمنــه محضــر القبــض وإقــرار املدعــى عليــه بــأن جميــع‬\n‫املســتندات عائــدة ملؤسســة ‪.....‬وأنهــا موجــودة يف منزلــه ولقولــه تعالــى‬\n‫((يأيهــا الذيــن آمنــوا ال تخونــوا اهلل والرســول وتخونــوا أماناتكــم وأنتــم‬\n‫تعلمــون )) وقولــه عليــه الصــاة والســام (املســلم مــن ســلم املســلمون مــن‬\n‫ا‬\n‫ا محرمـ ًا وفعـ ً‬  ‫لســانه ويــده) وألن مــا أقــدم عليــه املدعــى عليــه يعــد عمـ ً‬\n‫قبيحــا وليــس مــن األمانــة وألن مــا دفــع بــه املدعــى عليــه يعــد دفعـ ًا غيــر‬\n‫مقبــول ولــكل مــا تقــدم فقــد ثبــت لــدي إدانــة املدعــى عليــه ‪.....‬بخيانــة‬\n‫األمانــة مــن خــال االســتيالء علــى ملفــات ومســتندات ملشــاريع املؤسســة‬\n‫وإخفائهــا بقصــد اإلضــرار واملســاومة علــى إرجاعهــا وقــررت تعزيــره‬\n‫بالســجن مــدة ثمانيــة أشــهر يحتســب منهــا مــا أمضــاه موقوف ـ ًا يف هــذه‬\n‫القضية وجلده خمســة وثالثني جلدة مكررة أربع مرات بني كل مرة‬\n‫واألخــرى مــدة ال تقــل عــن أســبوع وذلــك للحقــن العــام واخلــاص مناصفــة‬\n‫بينهمــا ســجن ًا وجلــد ًا وبعــرض احلكــم علــى املدعــي العــام واملدعي باحلق‬\n‫اخلــاص واملدعــى عليــه قــرر املدعــي باحلــق اخلــاص القناعــة وقــرر املدعــى‬\n‫عليــه عــدم قناعتــه باحلكــم وطلــب تقــدمي الئحتــه االعتراضيــة فأفهمتــه‬\n‫مبراجعتنــا يف يــوم الســبت املوافــق ‪1434/1/3‬ه ـ الســتالم صــورة مــن‬\n‫احلكــم وتقــدمي الئحتــه خــال ثالثــن يومـ ًا مــن تاريخــه ولــم يبــد املدعــي‬\n‫العــام اعتراضــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n‫آلــه وصحبــه وســلم ‪ .‬احلمــد هلل والصــاة والســام علــى مــن ال نبــي بعــده‬\n‫وبعــد ‪ ،‬فقــد جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة الســابعة مبحكمــة‬\n‫االســتئناف يف منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة‬\n\n\n                                                                                         ‫‪32‬‬\n\f     ‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة جــدة املســاعد رقــم‬\n     ‫‪ 33948886‬وتاريــخ ‪1434/5/4‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n     ‫فضيلــة الشــيخ‪ ..... /‬القاضــي باحملكمــة اجلزائيــة مبحافظــة جــدة‬\n     ‫رقــم ‪ 344014‬وتاريــخ ‪1434/1/6‬ه ـ احملكــوم فيــه مبــا دون بباطــن‬\n     ‫القــرار املتضمــن دعــوى املدعــى العــام ضــد‪ ...../‬املتهــم يف خيانــة األمانــة‬\n     ‫وبدراســة القــرار وصــورة ضبطــه والالئحــة االعتراضيــة تقــررت املوافقــة‬\n     ‫علــى احلكــم‪ ،‬واهلل املوفــق ‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى الــه‬\n                                                                      ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪33‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"41499c81-d627-5952-8b7f-c01b2e788165","source_page_start":24,"source_page_end":33,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"33f29d4b9f3ed1674b26c67c65fc41542473fe7bcd5c9b1da0f1482726bbfc17","normalized_text_hash":"0d1f95ddd23704d4698bf838d0a9fb60301c8900747a9d885865ce5a52fd7fa1","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v27-p24-344014"},{"id":"653f725e-f10a-56a0-a8d3-c3937c2ef84b","document_type":"judgment","category":"judicial","subcategory":"general","title":"اختاس -اختاس مبالغ مالية من صرافات البنك -املتعدي واملفرط يضمن ما جنت يده -من فعل فعا لم يؤذن له فيه ضمن -التعزير بالقرائن .","document_number":"33471070","case_number":"33256253","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/30","year":"1434","subject":"اختاس -اختاس مبالغ مالية من صرافات البنك -املتعدي واملفرط يضمن ما جنت يده -من فعل فعا لم يؤذن له فيه ضمن -التعزير بالقرائن .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 33471070:‬تاريخه‪1433/11/30 :‬هـ‬\n                     ‫رقم الدعوى‪33256253 :‬‬\n        ‫قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34215341‬تاريخه‪1433/5/19 :‬هـ‬\n\n\n ‫اختــاس ‪ -‬اختــاس مبالــغ ماليــة مــن صرافــات البنــك ‪ -‬املتعــدي‬\n ‫واملفــرط يضمــن مــا جنــت يــده ‪ -‬مــن فعــل فعــا لــم يــؤذن لــه فيــه ضمــن‬\n                                                           ‫‪ -‬التعزيــر بالقرائــن ‪.‬‬\n\n\n\n                         ‫‪ .1‬القاعدة الفقهية ‪:‬أن اإلقرار ال يتعد صاحبه ‪.‬‬\n ‫‪ .2‬جــاء يف كشــاف القنــاع (ج‪/9‬ص ‪)406‬مــا نصــه (فــإن لــم يحرزهــا‬\n ‫الوديــع يف حــرز مثلهــا مــع عــدم التعيــن ضمنهــا ألنــه مفــرط أو ســعى‬\n ‫الوديــع بهــا إلــى ظالــم أو دل الوديــع عليهــا لصـ ًا فأخذها اللص ضمنها‬\n ‫الوديــع لتعديــه وتفريطــه ) أ‪.‬ه ـ جــاء يف الــروض املربــع (ج‪/5‬ص‪)458‬ما‬\n                  ‫نصــه (ويلزمــه أي املــودع حفظهــا يف حــرز مثلهــا عرفــا )‬\n ‫‪ .3‬كل مــن فعــل فعــا لــم يــؤذن لــه فيــه ضمــن مــا تولــد عنــه مــن ضــرر‬\n                       ‫ينظــر املوســوعة الفقهيــة الكويتيــة ( ج‪/28‬ص‪.)289‬‬\n ‫‪ .4‬وجــاء يف الشــرح الكبيــر ‪(12/13‬ويجــوز أن يضمــن احلــق للرجــل‬\n ‫الواحــد اثنــان أو أكثــر‪ )...‬إلــى أن قــال (‪ ..‬فــان ضمــن كل واحــد‬\n                ‫منهــم جميعــه بــرئ كل واحــد منهــم بــأداء أحدهــم )‬\n ‫‪ .5‬وجــاء أيضــا يف كشــاف القنــاع (ج‪ / 8‬ص‪ )299‬مــا نصــه ( ويصــح ان‬\n ‫يضمــن احلــق عــن املديــن الواحــد اثنــان فأكثــر‪ )...‬إلــى أن قــال (‪ ..‬فإن‬\n ‫قــاال كل واحــد منــا ضامــن لــك األلــف الــذي عليــه فهــو أي قولهمــا‬\n ‫ضمــان اشــتراك يف انفــراد ألنهمــا اشــتركا يف الضمــان وكل واحــد‬\n                     ‫ضامــن الديــن منفــردا بضمانــه لــه أي لــرب احلــق ) ‪.‬‬\n                                                                                      ‫‪34‬‬\n\f     ‫‪ -‬اتهــام املدعــي العــام للمدعــى عليهمــا بقيامهمــا باختــاس مبلــغ‬\n     ‫قــدره ( ‪ ) 1683400‬مليــون وســتمائة وثالثــة وثمانــون ألفــا وأربعمائــة‬\n     ‫ريــال مــن مجموعــة مــن صرافــات بنــك ‪ ...‬أثنــاء عملهمــا يف تغذيــة‬\n                    ‫الصرافات‪،‬يطلــب إثبــات مــا أســند إليهــم وتعزيرهــم ‪.‬‬\n     ‫حيــث إنــه مت القبــض علــى األول بتاريــخ ‪1433/2/13‬ه ـ وعلــى الثانــي‬\n     ‫بتاريــخ ‪1433/2/3‬ه ـ بنــاء علــى البــاغ املقــدم مــن الوكيــل الشــرعي‬\n     ‫عــن شــركة ‪ ، .........‬املتضمــن أن املدعــى عليهمــا اســتغال طبيعــة‬\n     ‫عملهمــا لــدى الشــركة يف تغذيــة صرافــات بنــك ‪ ...‬واختلســا مبلغــا‬\n     ‫قــدره ( ‪ ) 1683400‬مليــون وســتمائة وثالثــة وثمانــون ألفــا وأربعمائــة‬\n     ‫ريــال مــن مجموعــة مــن صرافــات بنــك ‪ ...‬وانتهــى التحقيــق إلــى توجيــه‬\n     ‫االتهــام إلــى املدعــى عليهمــا باختــاس مبلــغ قــدره ( ‪ ) 1683400‬مليــون‬\n     ‫وســتمائة وثالثــة وثمانــون ألفــا وأربعمائــة ريــال مــن مجموعــة مــن‬\n     ‫صرافــات بنــك ‪ ...‬أثنــاء عملهمــا يف تغذيــة الصرافــات ‪ ،‬وذلــك لألدلــة‬\n     ‫والقرائــن املرصــودة يف ملــف الدعــوى وباالطــاع علــى صحيفــة احلالــة‬\n     ‫اجلنائيــة لــم يعثــر للمدعــى عليــه األول علــى حالــة جنائيــة مســجلة وعثــر‬\n     ‫للمدعــى عليــه الثانــي قضيــه مســجله عليــه بتهمــة لــواط وتعريــة شــخص‬\n                                                  ‫وتصويــره لغــرض ســيئ والتهديــد‬\n     ‫ا مــا ذكــره املدعــي العــام يف دعــواه‬ ‫‪ -‬أجــاب املدعــى عليــه األول ‪ ...‬قائـ ً‬\n     ‫مــن تاريــخ القبــض صحيــح وأنــا لــم أقــم باختــاس املبلــغ املذكــور وال‬\n     ‫عالقــة لــي بــه وأنــا أعمــل يف شــركة التغذيــة لبنــك ‪ ...‬والرقــم الســري‬\n                                  ‫للتغذيــة ال يعرفــه إال أنــا واملدعــى عليــه الثانــي‬\n\n‫‪35‬‬\n\f‫‪ -‬أجــاب املدعــى عليــه الثانــي ‪ :‬مــا ذكــره املدعــي العــام مــن تاريــخ‬\n‫القبــض صحيــح وقــد كنــت مــع املدعــى عليــه األول أثنــاء عمليــة‬\n‫اإلختــاس وأعطانــي مبلغــا وقــدره أربعمائــة ألــف ريــال مقابــل التســتر‬\n‫والرقــم الســري لتغذيــة الصرافــات خــاص بــي وبــه وقــد ســلمت هــذا‬\n                                                ‫املبلــغ للشــركة ولــي اعتــراف ‪.‬‬\n‫‪-‬حضــر املدعــي باحلــق اخلــاص وكالة‪.....‬الوكيــل عــن شــركة ‪............‬‬\n‫مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل اخلبــر الثانيــة برقم ‪35066‬‬\n‫يف ‪1432/11/4‬ه ـ اجللــد ‪ 3000‬والتــي تخولــه حــق اإلقــرار واملرافعــة‬\n‫ا قــام املدعــى عليهمــا باختــاس مبلــغ وقــدره‬         ‫واملدافعــة وادعــى قائ ـ ً‬\n‫مليــون وســتمائة وثالثــة وثمانــون ألــف وأربعمائــة ريــال أعــاد املدعــى‬\n‫عليــه الثانــي أربعمائــة ألــف ريــال للشــركة فيصبــح مجمــوع مــا اطلبــه‬\n‫هــو مبلــغ وقــدره مليــون ومائتــان وثالثــة وثمانــون ألــف وأربعمائــة ريــال‬\n                             ‫اطلــب ســؤالهم واحلكــم عليهــم بدفــع املبلــغ ‪.‬‬\n‫ا مــا ذكــره املدعــي اخلــاص يف‬    ‫‪ -‬أجــاب كل واحــد منهمــا بانفــراد قائـ ً‬\n                                                               ‫دعــواه غيــر صحيــح ‪.‬‬\n                                                    ‫أدلة املدعي يف احلق اخلاص ‪:‬‬\n‫ا بتوقيــع املدعــى عليهمــا وقــد‬  ‫أوال‪ :‬ســند اســتالم املبالــغ يكــون مذي ـ ً‬\n                                       ‫صــادق املدعــى عليهمــا علــى توقيعاتهــم‪.‬‬\n‫ثاني ـ ًا ‪ :‬ورقــة تعهــد علــى املدعــى عليهمــا للشــركة بتحمــل أي خطــأ أو‬\n‫إهمــال تتعــرض لهــا املبالــغ املســتلمة وقــد صــادق املدعــى عليهمــا علــى‬\n                                                                               ‫ذلــك ‪.‬‬\n‫ثالثـ ًا ‪ :‬تعهــد بعــدم كشــف الرقــم الســري ألي أحــد وقــد خالفــوا التعهــد‬\n                                      ‫فكالهمــا يعــرف الرقــم الســري لآلخــر ‪.‬‬\n\n\n                                                                                         ‫‪36‬‬\n\f     ‫‪ -‬صــادق املدعــى عليهمــا علــى توقيعاتهــم يف املســتندات باالســتالم‬\n                                                                         ‫والتعهــدات‪.‬‬\n     ‫‪ -‬وبنــاء علــى مــا ســبق مــن الدعــوى وجوابهــا وحيــث أنكــر املدعــى‬\n     ‫عليهمــا االختــاس ولعــدم البينــة علــى االختــاس وألنــه أقــر كل‬\n     ‫واحــد منهمــا باشــتراكهما يف اســتالم جميــع املبالــغ ونظــرا ال قرارهمــا‬\n     ‫مبعرفــة كل واحــد منهمــا للرقــم الســري لآلخــر وهــو مخالــف لبنــود‬\n     ‫وعقــد الشــركة وحيــث إن مــا قــام بــه املدعــى عليهمــا فيــه إخــال‬\n     ‫باألمانــة وتضيعيهــا وفيــه تقصيــر يف حفــظ الوديعــة فإفشــاء كل واحــد‬\n     ‫منهمــا لألخــر بالرقــم الســري فيــه تعــدي وتفريــط يف حفــظ الوديعــة‬\n     ‫‪ ،‬صــدر احلكــم بثبــوت إدانــة املدعــي عليهمــا بالتفريــط والتعــدي يف‬\n                                  ‫حفــظ األمانــة والوديعــة واحلكــم مبــا يلــي ‪:‬‬\n     ‫أوال ‪ :‬ســجن املدعــى عليهمــا ملــدة ســنة حتتســب منهــا مــدة اإليقــاف‬\n     ‫وجلــد كل واحــد منهمــا مائــة جلــدة تعزيــرا علنــا مفرقــة علــى فترتــن‬\n                                                    ‫مناصفــة بينهمــا عشــرة أيــام ‪.‬‬\n     ‫ثانيــا ‪ :‬إلــزام املدعــى عليهمــا بدفــع املبلــغ املدعــى بــه وقــدره مليــون‬\n     ‫ومائتــان وثالثــة وثمانــون ألفـ ًا وأربعمائــة ريــال بالتضامــن حيــث ثبــت أن‬\n     ‫املبلــغ كامــا يف ذمــة كل واحــد منهمــا منفــردا ولــرب املــال أي املدعــي‬\n     ‫اخلــاص بالوكالــة مطالبــة احدهمــا أو كالهمــا بكامــل املبلــغ ويرجــع‬\n     ‫املدعــى عليهمــا كل واحــد منهمــا علــى اآلخــر فيمــا زاد يف دفعــه عــن‬\n                                                                              ‫اآلخــر ‪.‬‬\n     ‫‪ -‬قــرر املدعــى العــام واملدعــى عليهمــا االعتــراض وطلبــوا االســتئناف‬\n     ‫بتقــدمي لوائــح اعتراضيــة ‪ -‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n‫‪37‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.........‬القاضــي يف احملكمــة اجلزئيــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزئيــة يف محافظــة جدة‪/‬املســاعد برقــم ‪33256253‬‬\n‫وتاريــخ ‪ 1433/04/12‬ه ـ املقيــدة باحملكمــة برقــم ‪ 33679631‬وتاريــخ‬\n‫‪ 1433/04/11‬ه ـ ففــي يــوم االثنــن املوافــق‪ 1433/04/19‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 10 : 22‬وفيهــا حضــر املدعــي العــام ‪..........‬ســعودي‬\n‫مبوجــب الســجل املدنــي رقــم (‪ ).............‬واملكلــف مبوجــب اخلطــاب رقم‬\n‫‪ 24/56/2‬يف ‪1432/1/16‬ه ـ والصــادر مــن رئيــس دائــرة االدعــاء العــام‬\n‫ا بصفتــي مدعي ـ ًا عامــا بدائــرة االدعــاء‬  ‫مبحافظــة جــدة وادعــى قائ ـ ً‬\n‫العــام مبحافظــة جــدة أدعــي ‪ :‬علــى كال مــن ‪ )40( ،............ /1‬عامـ ًا‬\n‫‪ ،‬اجلنســية ســعودي مبوجــب الهويــة رقــم (‪ ، )..........‬احيــل الــى ســجون‬\n‫جــدة مبوجــب أمــر متديــد التوقيــف رقــم ‪ 11/36‬يف ‪ 1433/2/24‬ه ـ ‪/2‬‬\n‫‪ ،................‬اجلنســية ســعودي مبوجــب الهويــة رقــم (‪ ، )..........‬احيــل الى‬\n‫ســجون جــدة مبوجــب أمــر متديــد التوقيــف رقــم ‪ 11/26‬يف ‪1433/2/15‬‬\n‫ه ـ حيــث إنــه مت القبــض علــى األول بتاريــخ ‪1433/2/13‬هـ وعلى الثاني‬\n‫بتاريــخ ‪1433/2/3‬ه ـ بنــاء علــى البــاغ املقــدم مــن الوكيــل الشــرعي‬\n‫عــن شــركة ‪ ،........./‬ســعودي اجلنســية ‪ ،‬املتضمــن أن املدعــى عليهمــا‬\n‫اســتغال طبيعــة عملهمــا لــدى الشــركة يف تغذيــة صرافــات بنــك ‪...‬‬\n‫واختلســا مبلغــا قــدره ( ‪ ) 1683400‬مليــون وســتمائة وثالثــة وثمانــون‬\n‫ألفــا وأربعمائــة ريــال مــن مجموعــة مــن صرافــات بنــك ‪ ...‬عددهــا‬\n‫(‪ )11‬أحــد عشــر صرافــا مبحافظــة جــدة وقــد أعــاد املدعــى عليــه‬\n\n\n                                                                                       ‫‪38‬‬\n\f     ‫الثانــي‪ ........‬مبلــغ أربعمائــة ألــف ريــال إلــى الشــركة ‪ .‬وقــدم املدعــي‬\n     ‫تقريــرا محاســبيا مــن احملاســب القانونــي ‪........‬يتضمــن أن مجمــوع‬\n     ‫العجــز الكلــي هــو ( ‪ ) 1683400‬مليــون وســتمائة وثالثــة وثمانــون ألفــا‬\n     ‫وأربعمائــة ريــال‪ .‬وباســتجواب املدعــى عليــه األول أفــاد بأنــه يعمــل مــع‬\n     ‫الثانــي يف تغذيــة الصرافــات ببنــك ‪ ...‬وعندمــا طلــب تســلم األجهــزة منــه‬\n     ‫ألنــه لــم يعــد يرغــب االســتمرار يف هــذا العمــل فوجــئ بوجــود نقــص يف‬\n     ‫املبالــغ التــي مت جردهــا مــن أجهــزة الصــرف وناقصــة عــن املصــروف‬\n     ‫الفعلــي كمــا يتضــح مــن أوراق ( اجلورنــال ) اإللكترونــي التــي يطبعهــا‬\n     ‫اجلهــاز وال يعلــم كيــف حــدث هــذا العجــز ألنــه قــام بتغذيتهــا منــذ عشــرة‬\n     ‫أيــام تقريبــا ولــم يســجل ( اجلورنــال ) اإللكترونــي أي دخــول عليهــا‬\n     ‫منــذ تاريــخ دخولهــا وأن عملــه ســيتوقف لــدى الشــركة بعــد اإلجــراء‬\n     ‫النظامــي بتســلم األجهــزة وعمــل احملاضــر باالتفــاق مــع الشــركة أو‬\n     ‫إحالــة املوضــوع إلــى الشــرطة ‪.‬وباســتجواب املدعــى عليــه الثانــي اعتــرف‬\n     ‫بأنــه يعمــل لــدى الشــركة املذكــورة يف تغذيــة الصرافــات منــذ شــهرين‬\n     ‫مــع زميلــه املدعــى عليــه األول ‪.......‬ويف أثنــاء ذلــك اختلــس‪ .........‬مبالــغ‬\n     ‫ماليــة مــن تلــك الصرافــات وأعطــاه مبلــغ أربعمائة ألف ريــال على دفعات‬\n     ‫مقابــل ســكوته عنــه وكان يســتخدم رقــم املدعــى عليــه الثانــي فأبلــغ‬\n     ‫الشــركة قبــل أن يتــم اكتشــاف الشــركة لذلــك وأعــاد كامــل املبلــغ‬\n     ‫األربعمائــة ألــف ريــال إلــى الشــركة ‪ .‬وصــادق علــى اعترافــه شــرعا‬\n     ‫وبإجــراء املواجهــة بينهمــا أصــر املدعــى عليــه الثانــي علــى أقوالــه بأنــه‬\n     ‫اســتلم مــن املدعــى عليــه األول أربعمائــة ألــف ريــال عندمــا اكتشــف‬\n     ‫أمــره يف ســحب املبالــغ ليلتــزم الصمــت ‪ .‬وأقــر كل منهمــا بأنــه يعــرف‬\n     ‫رقــم اآلخــر الســري وأن فتــح الصرافــات ال يتــم اال بعــد ادخــال الرقمــن‬\n\n\n‫‪39‬‬\n\f‫العائديــن لهمــا وأن أي مبلــغ عجــز هــو حتــت مســئوليتهما‪ .‬وبإجــراء‬\n‫املواجهــة بينهمــا وبــن املديــر اإلقليمــي لشــركة ‪ ......‬اقــر املدعــى عليــه‬\n‫الثانــي بتســليم مبلــغ أربعمائــة ألــف ريــال للشــركة كان قــد اســتلمه‬\n‫مــن املدعــى عليــه األول الــذي أقــر بــأن املبلــغ املدعــى بــه يعتبــر عهــدة‬\n‫عليهمــا وانتهــى التحقيــق إلــى توجيــه االتهــام إلــى املدعــى عليهمــا‬\n‫باختــاس مبلــغ قــدره (‪ ) 1683400‬مليــون وســتمائة وثالثــة وثمانــون‬\n‫ألفــا وأربعمائــة ريــال مــن مجموعــة مــن صرافات بنك ‪ ...‬أثنــاء عملهما يف‬\n‫تغذيــة الصرافــات ‪ ،‬وذلــك لألدلــة والقرائــن املرصــودة يف ملــف الدعــوى‬\n‫وباالطــاع علــى صحيفــة احلالــة اجلنائيــة لــم يعثــر للمدعــى عليــه األول‬\n‫علــى حالــة جنائيــة مســجلة وعثــر للمدعــى عليــه الثانــي قضيــة مســجلة‬\n‫عليــه بتهمــة لــواط وتعريــة شــخص وتصويــره لغــرض ســيء والتهديــد‪.‬‬\n‫وحيــث إن مــا أقــدم عليــه املدعــى عليهمــا فعــل محــرم ومعاقــب عليــه‬\n‫شــرع ًا ‪ ،‬أطلــب إثبــات مــا نســب إليهمــا واحلكــم بتعزيرهمــا لقــاء ذلــك‪.‬‬\n‫علمــا بــأن احلــق اخلــاص مــا زال قائمــا يف املبلــغ املتبقــي (‪)1283400‬‬\n‫ريــال ‪ .‬هكــذا ادعــى وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه‬\n‫ا مــا ذكــره املدعــي العــام يف دعــواه مــن تاريــخ‬    ‫األول ‪.....‬أجــاب قائ ـ ً‬\n‫القبــض صحيــح وأنــا لــم أقــم باختــاس املبلــغ املذكــور وال عالقــة لــي‬\n‫بــه وأنــا أعمــل يف شــركة التغذيــة لبنــك ‪ ...‬والرقــم الســري للتغذيــة ال‬\n‫يعرفــه إال أنــا واملدعــى عليــه الثانــي وليــس علــى ســوابق هكــذا أجــاب‬\n‫ا مــا ذكــره املدعــي‬ ‫وبعــرض ذلــك علــى املدعــى عليــه الثانــي أجــاب قائـ ً‬\n‫العــام مــن تاريــخ القبــض صحيــح وقــد كنــت مــع املدعــى عليــه أثنــاء‬\n‫عمليــة االختــاس وأعطانــي مبلــغ وقــدره أربعمائــة ألــف ريــال مقابــل‬\n‫التســتر والرقــم الســري لتغذيــة الصرافــات خــاص بــي وبــه وعلــي ســابقة‬\n\n\n                                                                                      ‫‪40‬‬\n\f     ‫وقــد ســلمت هــذا املبلــغ للشــركة ولــي اعتــراف مصــدق شــرع ًا مبــا‬\n     ‫ذكــرت وحضــر يف هــذه اجللســة املدعــي باحلــق اخلــاص وكالــة ‪.........‬‬\n     ‫ســعودي مبوجــب الســجل املدنــي رقــم (‪ )............‬والوكيــل عــن شــركة‬\n     ‫‪ .................‬مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل اخلبــر الثانيــة‬\n     ‫برقــم ‪ 35066‬يف ‪1432/11/4‬ه ـ اجللــد ‪ 3000‬والتــي تخولــه حــق اإلقرار‬\n     ‫ا قــام املدعــى عليهمــا باختــاس مبلــغ‬      ‫واملرافعــة واملدافعــة وادعــى قائ ـ ً‬\n     ‫وقــدره مليــون وســتمائة وثالثــة وثمانــون ألف ـ ًا وأربعمائــة ريــال أعــاد‬\n     ‫املدعــى عليــه الثانــي أربعمائــة ألــف ريــال للشــركة فيصبــح مجمــوع مــا‬\n     ‫اطلبــه هــو مبلــغ وقــدره مليــون ومئتــان وثالثــة وثمانــون ألف ـ ًا وأربعمائــة‬\n     ‫ريــال اطلــب ســؤالهم واحلكــم عليهــم بدفــع املبلــغ هــذه دعــواي وبعرضهــا‬\n     ‫ا مــا ذكــره‬  ‫علــى املدعــى عليهمــا أجــاب كل واحــد منهمــا بانفــراد قائـ ً‬\n     ‫املدعــي اخلــاص يف دعــواه غيــر صحيــح هكــذا أجــاب كل واحــد‬\n     ‫منهمــا وبســؤال املدعــي اخلــاص عــن بينتــه قــال لــدى بينــة وأطلــب املهلــة‬\n     ‫إلحضارهــا ورفعــت اجللســة إلــى يــوم األحــد املوافــق ‪1433/5/2‬ه ـ‬\n             ‫الســاعة ‪ 9‬حــرر يف ‪1433/4/19‬ه ـ وأغلقــت اجللســة الســاعة ‪11‬‬\n     ‫ويف جلســة أخــرى افتتحــت اجللســة وحضــر فيهــا املدعــي العــام واملدعــى‬\n     ‫عليهمــا واملدعــي اخلــاص وحضــر يف هــذه اجللســة أيضـ ًا وكيــل املدعــى‬\n     ‫عليــه ‪ ...........‬ويدعــى ‪ ..........‬ســعودي مبوجــب الســجل املدنــي رقــم‬\n     ‫(‪ )...........‬مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل الســجن بجــدة‬\n     ‫برقــم ‪ 35‬يف ‪1433/3/29‬ه ـ املجلــد ‪/1‬أ‪/‬س والتــي تخولــه حــق املدافعــة‬\n     ‫واملرافعــة وبســؤال املدعــي اخلــاص عــن بينتــه التــي وعــد بهــا أجــاب‬\n     ‫ا‬‫ا بينتــي علــى النحــو التالــي أوال ســند اســتالم املبالــغ يكــون مذيـ ً‬   ‫قائـ ً‬\n     ‫بتوقيــع املدعــى عليهمــا وقــد صــادق املدعــى عليهمــا علــى توقيعاتهــم‬\n\n\n‫‪41‬‬\n\f‫ثاني ـ ًا ورقــة تعهــد علــى املدعــى عليهمــا للشــركة بتحمــل أي خطــأ أو‬\n‫إهمــال تتعــرض لهــا املبالــغ املســتلمة وقــد صــادق املدعــى عليهمــا علــى‬\n‫ذلــك ثالث ـ ًا تعهــد بعــدم كشــف الرقــم الســري ألي أحــد وقــد خالفــوا‬\n‫التعهــد فكالهمــا يعــرف الرقــم الســري لآلخــر هكــذا قــرر وبســؤال‬\n‫ا أطلــب املهلــة‬  ‫املدعــي اخلــاص عــن املســتندات والتعهــدات أجــاب قائ ـ ً‬\n‫إلحضارهــا وبعــرض ذلــك علــى املدعــى عليهمــا صادقــا علــى توقيعاتهــم‬\n‫يف املســتندات باالســتالم والتعهــدات وأضــاف املدعى عليــه األول ‪..........‬‬\n‫ا مــا ذكــره املدعــي غيــر صحيــح فأنــا لــم أختلــس أي شــيء وهــذا‬       ‫قائـ ً‬\n‫ا موكلــي ليــس‬      ‫اتهــام باطــل وأضــاف وكيــل املدعــى عليــه الثانــي قائـ ً‬\n‫ملم ـ ًا بالعمــل فليــس لــه إال زهــاء شــهرين تقريب ـ ًا فلذلــك لــم ينتبــه ملــا‬\n‫يحــدث متأخــر ًا هكــذا أجــاب وأضــاف كل واحــد مــن املدعــى عليهمــا‬\n‫ا الصرافــات التــي فيهــا عجــز هــي مــن اختصــاص عملنــا يف التغذيــة‬       ‫قائـ ً‬\n‫باملــال وال أحــد يغذيهــا باملــال إال نحــن هكــذا قــرر كل واحــد منهمــا‬\n‫ويف جلســة أخــرى افتتحــت اجللســة وفيهــا حضــر املدعــي العــام واخلــاص‬\n‫بالوكالــة واملدعــى عليهمــا وبدراســة وتأمــل مــا ســبق ضبطــه جــرى‬\n‫ســؤال املدعــي العــام واخلــاص بالوكالــة ألديكمــا زيــادة بينــة فأجــاب‬\n‫كل واحــد منهمــا قائــا ليــس لدينــا ســوى مــا جــاء يف أوراق املعاملــة‬\n‫هكــذا أجــاب وقــد جــرى االطــاع علــى أوراق املعاملــة ولــم أجــد بــن‬\n‫لفاتهــا وعلــى طياتهــا مــا ثبــت اختــاس ونصــب واحتيــال املدعــى عليهمــا‬\n‫وجــرى االطــاع علــى إقــرار املدعــى عليــه الثانــي ‪.....‬يف اللفــة رقــم (‪)2‬‬\n‫صحيفــة (‪ )3‬فألفيتــه غيــر كايف إلثبــات اإلدانــة علــى املدعــى عليــه‬\n‫الثانــي وعلــى املدعــى عليــه األول‪ ........‬ألن اإلقــرار كمــا قــرر الفقهــاء‬\n‫ال يتعــدى صاحبــه واملدعــى عليــه الثانــي ‪............‬كمــا هــو مــدون يف‬\n\n\n                                                                                         ‫‪42‬‬\n\f     ‫إقــرار ه املصــدق شــرعا اعتــرف بأنــه اســتلم املبلــغ املشــار إليــه يف إقــراره‬\n     ‫املصــدق شــرعا واعتــرف انــه علــم باختــاس زميلــه ‪......‬وأعطــاه مبلــغ‬\n     ‫مقابــل ســكوته ولــم يكــن يعلــم بــأن زميلــه قــد اختلــس باســتخدام‬\n     ‫رقمــه الســري وفــور علمــه ابلــغ الشــركة وأعطاهــم املبلــغ وبنــاء علــى مــا‬\n     ‫ســبق مــن الدعــوى وجوابهــا وحيــث أنكــر املدعــى عليهمــا االختــاس‬\n     ‫والنصــب واالحتيــال واقــر كل واحــد منهمــا باشــتراكهما يف اســتالم‬\n     ‫جميــع املبالــغ ونظــرا إلقرارهمــا مبعرفــة كل واحــد منهمــا للرقــم‬\n     ‫الســري لآلخــر وهــو مخالــف لبنــود وعقــد الشــركة وحيــث أن مــا‬\n     ‫قــام بــه املدعــى عليهمــا فيــه إخــال باألمانــة وتضيعيهــا وفيــه تقصيــر‬\n     ‫يف حفــظ الوديعــة فإفشــاء كل واحــد منهمــا لآلخــر بالرقــم الســري‬\n     ‫فيــه تعــدي وتفريــط يف حفــظ الوديعــة وقــد جــاء يف كشــاف القنــاع‬\n     ‫(ج‪/9‬ص ‪ )406‬مــا نصــه (فــإن لــم يحرزهــا الوديــع يف حــرز مثلهــا مــع‬\n     ‫عــدم التعيــن ضمنهــا ألنــه مفــرط أو ســعى الوديــع بهــا إلــى ظالــم أو دل‬\n     ‫الوديــع عليهــا لصــا فأخذهــا اللــص ضمنهــا الوديــع لتعديــه وتفريطــه )‬\n     ‫أ‪.‬ه ـ وهنــا قــد عــن املــودع للوديــع كيفيــة حفظهــا بعــدم إفشــاء الرقــم‬\n     ‫الســري وهــذا يعتبــر عرفــا حــرز ملثلهــا وقــد جــاء يف الــروض املربــع (ج‪/5‬‬\n     ‫ص‪)458‬مــا نصــه (ويلزمــه أي املــودع حفظهــا يف حــرز مثلهــا عرفــا )‬\n     ‫والن كل مــن فعــل فعــا لــم يــؤذن لــه فيــه ضمــن مــا تولــد عنــه مــن ضــرر‬\n     ‫ينظــر املوســوعة الفقهيــة الكويتيــة ( ج‪/28‬ص‪ )289‬وحيــث أن املدعــى‬\n     ‫عليهمــا اشــتركا يف اســتالم املبالــغ كلهــا ســوية فيضمــن كل واحــد‬\n     ‫منهمــا املبلــغ كامــا يف ذمتــه ولــرب املــال أن يطلــب املــال مــن أحدهمــا‬\n     ‫أو كالهمــا ألنهمــا باشــتراكهما يف اســتالم املبالــغ والتفريــط يف عــدم‬\n     ‫حفظهــا ضمــن كل واحــد منهمــا املبلــغ كامــا يف ذمتــه وذلــك ملــا جــاء‬\n\n\n‫‪43‬‬\n\f‫يف الشــرح الكبيــر ( ج‪/13‬ص‪ )12‬ونصــه (ويجــوز أن يضمــن احلــق‬\n‫للرجــل الواحــد اثنــان أو أكثــر‪ )...‬إلــى أن قــال (‪ ..‬فــان ضمــن كل واحــد‬\n‫منهــم جميعــه بــرئ كل واحــد منهــم بــأداء أحدهــم ) وجــاء أيضــا يف‬\n‫كشــاف القنــاع (ج‪ / 8‬ص‪ )299‬مــا نصــه ( ويصــح أن يضمــن احلــق عــن‬\n‫املديــن الواحــد اثنــان فأكثــر‪ )...‬إلــى أن قــال (‪ ..‬فــإن قــاال كل واحــد‬\n‫منــا ضامــن لــك األلــف الــذي عليــه فهــو أي قولهمــا ضمــان اشــتراك يف‬\n‫انفــراد ألنهمــا اشــتركا يف الضمــان وكل واحــد ضامــن الديــن منفــردا‬\n‫بضمانــه لــه أي لــرب احلــق ) أ‪.‬ه ـ واشــتراك املدعــى عليهمــا يف اســتالم‬\n‫الوديعــة وعــدم حفظهــا يوجــب عليهمــا ضمــان اشــتراك يف انفــراد والن‬\n‫املدعــى عليــه األول ‪.....‬ليــس عليــه ســابقة مــن نفــس النــوع وألن إقــراره‬\n ‫املصــدق شــرعا املشــار إليــه أعــاه يفيــد الشــبهة ومعرفــة كل واحــدٍ‬\n‫منهمــا للرقــم الســري لآلخــر قرينــة تفيــد الشــبهة باالختــاس وجلميــع‬\n‫مــا ســبق فقــد ثبــت لــدى إدانــة املدعــي عليهمــا بالتفريــط والتعــدي يف‬\n‫حفــظ األمانــة والوديعــة وحكمــت مبــا يلــي ‪ :‬أوال ســجن املدعــى عليهمــا‬\n‫ملــدة ســنة حتتســب منهــا مــدة اإليقــاف وجلــد كل واحــد منهمــا مائــة‬\n‫جلــدة تعزيــرا علنــا مفرقــة علــى فترتــن مناصفــة بينهمــا عشــرة أيــام‬\n‫لقــاء تفريطهمــا يف حفــظ الوديعــة وشــبهة االختــاس هــذا يف احلــق‬\n‫العــام ثانيــا ألزمــت املدعــى عليهمــا بدفــع املبلــغ املدعــى بــه وقــدره مليــون‬\n‫ومائتــان وثالثــة وثمانــون ألف ـ ًا وأربعمائــة ريــال بالتضامــن حيــث ثبــت‬\n‫لــدي املبلــغ كامــا يف ذمــة كل واحــد منهمــا منفــردا ولــرب املــال أي‬\n‫املدعــي اخلــاص بالوكالــة مطالبــة احدهمــا أو كالهمــا بكامــل املبلــغ‬\n‫ويرجــع املدعــى عليهمــا كل واحــد منهمــا علــى اآلخــر فيمــا زاد يف دفعــه‬\n‫عــن اآلخــر هــذا يف احلــق اخلــاص وبذلــك كلــه حكمــت وبعرضــه علــى‬\n\n\n                                                                                          ‫‪44‬‬\n\f     ‫املدعــي العــام واملدعــى عليهمــا قــررا عــدم القناعــة وافهــم كل واحــد‬\n     ‫منهمــا بــأن عليهــم تقــدمي الئحــة اعتراضيــة خــال مــدة ثالثــن يوم ـ ًا‬\n     ‫مــن اســتالم نســخة احلكــم خــال عشــره أيــام وإال ســقط حقهــم يف‬\n     ‫االعتــراض وقنــع بذلــك املدعــي باحلــق اخلــاص وكالــة وأغلقــت اجللســة‬\n     ‫الســاعة ‪ .1:15‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                   ‫آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1433/11/29‬هــ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..........‬القائــم بعمــل فضيلــة الشــيخ‬\n     ‫‪ ..........‬القاضــي باملكتــب القضائــي الثامــن بهــذه احملكمــة مبوجــب‬\n     ‫خطــاب التكليــف رقــم ‪ 341071833‬تاريــخ ‪1434/05/04‬ه ـ ـ ففــي‬\n     ‫يــوم األحــد املوافــق ‪1434/6/18‬ه ـ افتتحــت اجللســة الســاعة (‪)10:00‬‬\n     ‫وقــد عــادت املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة‬\n     ‫باخلطــاب رقــم ‪ 34747762‬يف ‪1434/6/11‬ه ـ حيــث جــرى تدقيــق‬\n     ‫احلكــم مــن قبــل الدائــرة اجلزائيــة األولــى مبحكمة االســتئناف واملظهر‬\n     ‫علــى القــرار برقــم ‪ 34215341‬يف ‪1434/5/19‬ه ـ ونصــه ‪(-:‬وبدراســة‬\n     ‫القــرار وصــورة ضبطــه قررنــا املوافقــة علــى احلكــم بعــد اإليضــاح‬\n     ‫األخيــر وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n     ‫وســلم قاضــي اســتئناف ‪ ...........‬ختــم وتوقيــع قاضــي اســتئناف ‪.........‬‬\n     ‫ختــم وتوقيــع رئيــس الدائــرة ‪.............‬ختــم وتوقيــع وبيــان للواقــع جــرى‬\n     ‫إحلاقــه بضبطــه وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n     ‫وأغلقــت اجللســة الســاعة ‪ 10:15‬حــرر يف ‪1434/6/18‬ه ـ وباهلل التوفيق‬\n                      ‫وصلــى اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪45‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"41499c81-d627-5952-8b7f-c01b2e788165","source_page_start":34,"source_page_end":45,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"21af408b2a595624007e2b91f130bda5dc594582deaf166dcfbc608f46567f80","normalized_text_hash":"b6184503b25a69a58fdec5daa47c8dda13a26c4f9df33a303bac889000ee465e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v27-p34-33471070"},{"id":"92828007-6bf0-5d04-98e5-38973c70b3d8","document_type":"judgment","category":"judicial","subcategory":"general","title":"نصب واحتيال -مساهمة -جمع أموال الناس بقصد املساهمات وإيهامهم بتوظيفها -ثبوت اإلدانة باإلقرار -موجب التعزير.","document_number":"34187716","case_number":"33568526","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/04/14","year":"1434","subject":"نصب واحتيال -مساهمة -جمع أموال الناس بقصد املساهمات وإيهامهم بتوظيفها -ثبوت اإلدانة باإلقرار -موجب التعزير.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34187716 :‬تاريخه‪1434/04/14 :‬هـ‬\n                    ‫رقم الدعوى‪33568526 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 341674860‬تاريخه‪1434/8/23 :‬هـ‬\n\n\n ‫نصــب واحتيــال ‪ -‬مســاهمة ‪ -‬جمــع أمــوال النــاس بقصــد املســاهمات‬\n      ‫وإيهامهــم بتوظيفهــا ‪ -‬ثبــوت اإلدانــة باإلقــرار ‪ -‬موجــب التعزيــر‪.‬‬\n\n\n\n\n ‫‪-1‬قولــه صلــى اهلل عليــه وســلم (كل املســلم علــى املســلم حــرام دمــه‬\n                                                         ‫ومالــه وعرضــه )‪.‬‬\n ‫‪ -2‬قولــه صلــى اهلل عليــه وســلم (إن دماءكــم وأعراضكــم وأموالكــم‬\n ‫عليكــم حــرام كحرمــة يومكــم هــذا يف شــهركم هــذا يف بلدكــم هذا)‪.‬‬\n\n\n\n\n ‫اتهــام املدعــي العــام املدعــى عليــه بقيامــه بالنصــب واالحتيــال عــن‬\n ‫طريــق جمــع أمــوال النــاس وإيهــام أصحابهــا بتوظيفهــا مبكاســب‬\n ‫وهميــة يطلــب إثبــات مــا أســند إليــه ومجازاتــه بعقوبــة تعزيريــة لقــاء‬\n ‫ذلــك‪ ،‬حيــث إنــه تقــدم عــدد مــن األشــخاص مــن ســكان مركــز ‪....‬‬\n ‫بدعــوى النصــب واالحتيــال ضــد املدعــى عليــه املذكــور بقيامــه بأخــذ‬\n ‫أموالهــم وإضاعــة حقوقهــم وتــورط املدعــى عليــه يف قضايــا املســاهمات‬\n ‫املشــبوهة ومت إحالتهــا لدائــرة التحقيــق يف قضايــا االعتــداء علــى املــال‬\n ‫مبحافظــة جــدة إلكمــال الــازم ‪ -‬أنكــر املدعــى عليــه مــا جــاء يف‬\n ‫الدعــوى ‪ -‬جــرى الرجــوع إلــى اعتــراف املدعــى عليــه تعقبـ ًا ورصــد نصــه‬\n                                                                                   ‫‪46‬‬\n\f     ‫وهــو يتضمــن صحــة مــا نســب إليــه ‪ -‬صــادق املدعــى عليــه علــى هــذا‬\n                                                                             ‫االعتــراف ‪.‬‬\n     ‫‪ -1‬صــدر احلكــم بثبــوت إدانــة املدعــى عليــه بالنصــب واالحتيــال عــن‬\n     ‫طريــق جمــع أمــوال النــاس وإيهــام أصحابهــا بتوظيفهــا مبكســب وهمــي‬\n                                                                  ‫واحلكــم مبــا يلــي ‪:‬‬\n     ‫‪ -2‬بســجنه ملــدة خمــس عشــرة ســنة حتســب منهــا مــدة إيقافــه علــى ذمــة‬\n                                                                               ‫التحقيــق ‪.‬‬\n     ‫‪ -3‬جلــده أربعــة أالف ســوط علــى دفعــات كل دفعــة خمســون ســوط ًا‬\n                 ‫وبــن كل دفعــة والتــي تليهــا مــدة ال تقــل عــن خمســة أيــام ‪.‬‬\n     ‫‪-‬قــرر املدعــي العــام واملدعــى عليــه عــدم القناعــة وطلبــا االســتئناف ‪-‬‬\n                                       ‫صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.......‬القاضــي يف احملكمــة اجلزائيــة‬\n     ‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n     ‫احملكمــة اجلزائيــة يف محافظــة جدة‪/‬املســاعد برقــم ‪33568526‬‬\n     ‫وتاريــخ ‪ 1433/09/10‬ه ـ املقيــدة باحملكمــة برقــم ‪331674860‬‬\n     ‫وتاريــخ ‪ 1433/09/09‬ه ـ ففــي يــوم األربعــاء املوافــق‪ 1433/10/18‬ه ـ‬\n     ‫افتتحــت اجللســة الســاعة ‪ 12 : 00‬وفيهــا حضــر املدعــي العــام ‪...........‬‬\n     ‫املكلــف باالدعــاء العــام مبوجــب خطــاب هيئــة التحقيــق واالدعــاء‬\n     ‫العــام رقــم ‪ 15832‬وتاريــخ ‪1433/3/6‬ه ـ وأدعــى قائــا بصفتــي‬\n     ‫عضــوا بدائــرة التحقيــق واالدعــاء العــام مبحافظــة جــدة فإنــي أدعــي‬\n     ‫علــى‪ .............‬البالــغ مــن العمــر ‪ 35‬عام ـ ًا (اجلنســية ســعودي) مبوجــب‬\n\n‫‪47‬‬\n\f‫الســجل املدنــي رقــم (‪ )............‬موقــوف بســجون جــدة علــى ذمــة قضايــا‬\n‫أخــرى حيــث إنــه بتاريــخ ‪1433/2/7‬ه ـ وردنــا خطــاب صاحــب الســمو‬\n‫امللكــي أميــر منطقــة مكــة املكرمــة رقــم (‪ /600178‬ص س) املبنــي‬\n‫علــى تعميــم صاحــب الســمو امللكــي ولــي العهــد نائــب رئيــس مجلــس‬\n‫الــوزراء وزيــر الداخليــة رقــم (‪ )5192‬يف ‪1433/1/19‬ه ـ القاضــي‬\n‫بإحالــة قضايــا توظيــف األمــوال لهيئــة التحقيــق واالدعــاء العــام حيــث‬\n‫أنــه تقــدم عــدد مــن األشــخاص مــن ســكان مركــز ‪ ............‬بدعــوى‬\n‫النصــب االحتيــال ضــد املدعــى عليــه املذكــور بقيامــه بأخــذ أموالهــم‬\n‫وإضاعــة حقوقهــم وتــورط املدعــى عليــه يف قضايا املســاهمات املشــبوهة‬\n‫ومت إحالتهــا لدائــرة التحقيــق يف قضايــا االعتــداء علــى املــال مبحافظــة‬\n‫جــدة إلكمــال الــازم وقيــدت بقيــد الــوارد العــام برقــم ( ‪ ) 8647‬وتاريــخ‬\n‫‪1433/3/1‬ه ـ و باســتجواب املدعــى عليــه ‪ /‬أقــر بأنــه يف بدايــة نشــاط‬\n‫ســوق األســهم منــذ حوالــي ثمــان ســنوات ولوجــود شــخص يدعــى ‪........‬‬\n‫وهــو شــريك ‪..........‬املعــروف يف مســاهمة ‪ .......‬املشــهورة وبحكــم‬\n‫كونــه يحمــل نفــس اســم القبيلــة فقــد ســألوه عنــه فحــاول هــو التوصــل‬\n‫إليــه بهــدف االســتفادة منــه وعنــد وصولــه للمدعــو ‪........... /‬طلــب منــه‬\n‫املســاهمة معــه فرفــض بحجــة أن املبلــغ املقــدم ليــس كافيــا إلدخالــه‬\n‫الســوق فقــام بجمــع مبالــغ ماليــة أكثــر ثــم تفاجــأ بإيقــاف ‪........‬‬\n‫وشــريكه نشــاطهما بهــدف اإليهــام والدعايــة فقــام مبحاولــة إعــادة‬\n‫األمــوال ألصحابهــا حســب زعمــه فرفضــوا ذلــك فقــام بتوزيــع أربــاح لهــم‬\n‫مــن رأس املــال الــذي قــام بأخــذه منهــم دون أن يكــون لهــذه املبالــغ أي‬\n‫أربــاح حيــث حصــل علــى مبالــغ ماليــة مــن مســاهمني تصــل إلــى أكثــر‬\n‫مــن ثالثمائــة وســتون مليــون ريــال وقــد تصــرف يف مبالــغ ماليــة بالهبــات‬\n\n\n                                                                                   ‫‪48‬‬\n\f     ‫ألصدقائــه ولعــدد مــن األشــخاص والصدقــات للجمعيــات اخليريــة وأفــاد‬\n     ‫أنــه تبقــى لديــه مبلــغ مالــي وقــدره مائــة وخمســون مليــون ريــال فقــام‬\n     ‫بتســليم هــذه األمــوال للشــركة األوربيــة بهــدف تعويــض النقــص يف هذه‬\n     ‫األمــوال إال أنــه تعــرض للنصــب واالحتيــال مــن الشــركة وأقــام عليهــا‬\n     ‫دعــوى ‪ ،‬كمــا أضــاف أنــه لــم يتملــك أي عقــار أو مقتنيــات عينيــة مــن‬\n     ‫هــذه األمــوال ولــم يقــم بشــراء أي أســهم ولــم يســاهم مــع أي مــن مشــغلي‬\n     ‫األمــوال و مبخاطبــة إدارة املباحــث العامــة باخلطــاب رقــم ‪/600188‬ص‬\n     ‫س يف ‪1431/2/9‬ه ـ مــن قبــل جلنــة توظيــف األمــوال حيــال وضــع املدعــى‬\n     ‫عليــه املذكــور وردت إفادتهــم بخطابهــم رقــم ‪/7/18‬ب‪ 17445/‬يف‬\n     ‫‪1431/3/9‬هـ املتضمنة عدم وجود قيود أمنية مســجلة عليه ومبخاطبة‬\n     ‫أمانــة محافظــة جــدة وردت إفادتهــم املتضمنــة انــه لــم تظهــر بيانــات أي‬\n     ‫تصاريــح بنــاء أو تصاريــح محــات جتاريــة ومبخاطبــة وزارة التجــارة‬\n     ‫والصناعــة وردت إفادتهــم املتضمنــة أن الــوزارة لــم يســبق لهــا الترخيــص‬\n     ‫للمذكــور بطــرح أي مســاهمة عقاريــة ومبخاطبــة شــرطة محافظــة جدة‬\n     ‫وردت إفادتهــم املتضمنــة أن املدعــى عليــه مطالــب مببلــغ وقــدره تســعة‬\n     ‫ماليــن وخمســمائة وأربعــة وخمســون ألــف ريــال مبوجــب قــرار مكتــب‬\n     ‫الفصــل يف منازعــات األوراق التجاريــة املرفــق بالقضيــة ومبخاطبــة هيئــة‬\n     ‫ســوق املــال وردت إفادتهــم املرفــق بهــا تقريــر عــن احملافــظ االســتثمارية‬\n     ‫للمدعــى عليــه املذكــور ومبخاطبــة وزارة التجــارة والصناعــة مبكــة‬\n     ‫املكرمــة وردت إفادتهــم املتضمنــة عــدم وجــود ســجالت جتاريــة‬\n     ‫للمدعــى عليــه املذكــور ومبخاطبــة محافــظ مؤسســة النقــد العربــي‬\n     ‫الســعودي لإلفــادة عــن حســابات املدعــى عليــه املذكــور وردت إفادتهــم‬\n     ‫املرفــق بهــا بيانــات املســتفيدين مــن العمليــات احلســابية املنفــذة علــى‬\n\n\n‫‪49‬‬\n\f‫حســاب املدعــى عليــه املذكــور وبالبحــث عــن ســوابق املتهــم املذكــور‬\n‫اتضــح وجــود ســابقة تزويــر وثائــق رســمية وقــد انتهــى التحقيــق إلــى‬\n‫توجيــه االتهــام لــ‪ ........../‬بالنصــب واالحتيــال عــن طريــق جمــع أمــوال‬\n‫النــاس وإيهــام أصحابهــا بتوظيفهــا مبكاســب وهميــة وذلــك لألدلــة‬\n‫والقرائــن التاليــة مــا ورد باعترافــه املنــوه عنــه واملــدون مبلــف التحقيــق‬\n‫املرفــق لفــة (‪ )7‬األحــكام الصــادرة مــن مكتــب الفصــل يف األوراق‬\n‫التجاريــة املرفقــة واملنــوه عنهــا بخطــاب شــرطة محافظــة جــدة املشــار‬\n‫إليــه مــا ورد بكشــوفات احلســابات البنكيــة للمدعــى عليــه املذكــور‬\n‫املرفقــة بخطــاب محافــظ مؤسســة النقــد العربــي الســعودي املرفــق‬\n‫بالقضيــة مــا ورد بتقريــر هيئــة ســوق املــال عــن احملافــظ االســتثمارية‬\n‫للمدعــى عليــه املذكــور املنــوه عنــه واملرفــق بالقضيــة وحيــث إن مــا‬\n‫ا محظــور ًا ومعاقــب عليــه نظام ـ ًا‬  ‫أقــدم عليــه املدعــى عليــه يعــد فع ـ ً‬\n‫فإنــي أطلــب إثبــات مــا أســند إليــه ومجازاتــه بعقوبــة تعزيريــة لقــاء ذلــك‬\n‫(علم ـ ًا أن احلــق اخلــاص مــازال قائم ـاً) وبعــرض مــا ورد بدعــوى املدعــي‬\n‫العــام علــى املدعــى عليــه احلاضــر يف املجلــس الشــرعي قــرر قائــا مــا‬\n‫ورد يف دعــوى املدعــي العــام ضــدي مــن توجيــه االتهــام لــي بالنصــب‬\n‫واالحتيــال عــن طريــق جمــع أمــوال النــاس وإيهــام أصحابهــا بتوظيفهــا‬\n‫مبكاســب وهميــة فغيــر صحيــح جملــة وتفصيــا وعليــه فقــد جــرى‬\n‫ســؤال املدعــي العــام هــل لديــه بينــه علــى مــا ذكــر قــال نعــم وبينتــي‬\n‫تتمثــل يف اعترافــه املنــوه عنــه واملــدون مبلــف التحقيــق املرفــق لفــة (‪)7‬‬\n‫األحــكام الصــادرة مــن مكتــب الفصــل يف األوراق التجاريــة املرفقــة‬\n‫واملنــوه عنهــا بخطــاب شــرطة محافظــة جــدة املرفــق بالقضيــة مــا ورد‬\n‫بكشــوفات احلســابات البنكيــة للمتهــم املذكــور املرفقــة بخطــاب‬\n\n\n                                                                                      ‫‪50‬‬\n\f     ‫محافــظ مؤسســة النقــد العربــي الســعودي املرفــق بالقضيــة وعليــه فقــد‬\n     ‫جــرى رفــع اجللســة لالطــاع علــى أوراق املعاملــة وجــرى قفلهــا يف متــام‬\n     ‫الســاعة الثانيــة عشــرة والربــع ظهــر ًا وبــاهلل التوفيــق وصلــى اهلل علــى‬\n          ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1433/10/18‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافق‪1434/02/20‬هـ فتحت‬\n     ‫اجللســة وفيهــا حضــر الطرفــان وجــرى عــرض إقــرار املدعــى عليــة علــى‬\n     ‫الصفحــة رقــم (‪ )3،2،1‬مــن دفتــر التحقيــق املرفــق باملعاملــة علــى اللفــة‬\n     ‫رقم (‪ )7‬علي املدعى عليه ونصه (يف البداية ومنذ حوالي ثمان ســنوات‬\n     ‫وكمــا تعلمــون حصلــت طفــرة يف ســوق املــال وانتشــرت ظاهــرة تشــغيل‬\n     ‫األمــوال باألســهم والبورصــة واملســاهمات العقاريــة واملاليــة وكان مــن‬\n     ‫ضمــن هــؤالء املشــغلني شــخص معــروف ومشــهور هــو ‪.....‬وهــو شــريك‬\n     ‫مــع ‪.......‬يف مســاهمات بطاقــات ســوا املشــهورة وبحكــم تشــابه االســم‬\n     ‫األخيــر يف القبيلــة ســألني كثيــر مــن املــأ عنه فحاولــت بعدها الوصول‬\n     ‫إليــه بهــدف االســتفادة منــه حاليـ ًا مــن خــال املبالــغ املوجــودة عندي ومن‬\n     ‫خــال املبالــغ األخــرى التــي أتوســط فيهــا للمســاهمني وفعــا اســتطعت‬\n     ‫الوصــول إليــه ولكــن طلــب منــي مبلــغ مالــي اكبــر ال يقــل عــن ثمانيــة‬\n     ‫ماليــن تقريب ـ ًا حيــت يســتطيع إدخــال هــذه املبالــغ للســوق لديــه وقمــت‬\n     ‫علــى الفــور بجمــع هــذه املبالــغ واجتهــت إليــه لتســليمه املبلــغ ولكنــي‬\n     ‫تفاجــأت بإيقافــه للنشــاط مؤقتــا واتضــح الحقـ ًا انــه كنــوع مــن الدعايــة‬\n     ‫والتالعــب وقمــت مبحاولــة إعــادة هــذه املبالــغ إلــى أصحابهــا ولكنهــم‬\n     ‫رفضــوا هــذا التصــرف وواجهــت ضغــط شــديد وتهديــد مــن قبــل بعضهم‬\n     ‫بشــكل ال ميكــن تصــوره ممــا اضطــررت معــه إلــى التصــرف بشــكل‬\n     ‫مؤقــت بتوزيــع أربــاح مــن رأس املــال علــى أســاس نقــوم بتعويــض ذلــك‬\n\n\n‫‪51‬‬\n\f‫بأقــرب فرصــة عــن طريــق مشــغلني آخريــن وكانــت الفرصــة يف ذلــك‬\n‫الوقــت ممكنــة وفعــا حاولــت الوصــول إلــى عــدد مــن املشــغلني اذكــر‬\n‫منهــم ‪......‬و‪........‬لكــن عجــزت عــن الوصــول إلــى أي منهــم ويف خــال‬\n‫هــذه الفتــرة كانــت املبالــغ تتضخــم بشــدة وأنــا مســتمر يف توزيــع األرباح‬\n‫حتــى أجــد حــل لتشــغيل هــذه املبالــغ ولكنــي عجــزت عــن حتقيــق ذلــك‬\n‫حتــى وصلــت األمــوال إلــى حــد ال ميكــن حتملــه وأحسســت بطــول األمــر‬\n‫وقمــت مبحاولــة تــايف هــذه املشــكلة باجتمــاع مــع رؤســاء املجموعــات‬\n‫مــن قبــل أقــارب لــي بشــرح املوضــوع لهــم كونــي اســتطيع مقابلــة هــؤالء‬\n‫ألنهــم يرونــي مســئوال أمامهــم عــن أموالهــم وصارحتهــم احلقيقيــة بــان‬\n‫املتبقــي مــن أمولهــم هــو مبلــغ مائــه وخمســون مليــون ريــال مــن أصــل‬\n‫مبلــغ ثالثمائــة وعشــرون مليــون ريــال وقمــت باالتفــاق علــى وضــع اليــه‬\n‫لتشــغيل هــذا املبلــغ بهــدف تعويــض رأس املــال ولكــن املفاجئــة انــه مت‬\n‫تســليم املبلــغ للشــركة األوربيــة عــن طريــق ابــن شــيخ القبيلــة الــذي‬\n‫جلــأت إليــة وكنــا ضحيــة هــذه الشــركة وقــد تقدمنــا بشــكوى ضــد‬\n‫هــذه الشــركة فتــم بفضــل اهلل القبــض علــى األشــخاص الذيــن كانــوا‬\n‫خلــف هــذه الشــركة وصــدر بحقهــم أحــكام جتاريــة وهــي قيــد التنفيذ‬\n‫حيــث يقضــون عقوبــة الســجن يف الريــاض والزالــت األمــوال يف ذمتهــم )‬\n‫فصــادق علــى جميــع مــا ورد فبنــاء علــى مــا تقــدم عــن الدعــوى واإلجابــة‬\n‫ومصادقــة املدعــى عليــة علــى مــا ورد يف إقــراره املــدون علــى الصفحــة‬\n‫رقــم ‪ 1،2،3‬مــن دفتــر التحقيــق وحيــث إن املدعــى عليــة قــد قــام بجمــع‬\n‫مبالــغ كبيــرة وقــام بإيهــام أصحابهــا باألربــاح عــن طريــق التوزيــع عليهــم‬\n‫مــن رأس املــال ولقولــه صلــى اهلل عليــة وســلم (كل املســلم علــى املســلم‬\n‫حــرام دمــه ومالــه وعرضــه ) ولقولــه صلــى اهلل عليــه وســلم (إن دمائكــم‬\n\n\n                                                                                     ‫‪52‬‬\n\f     ‫وأعراضكــم وأموالكــم عليكــم حــرام كحرمــة يومكــم هــذا يف‬\n     ‫شــهركم هــذا يف بلدكــم هــذا) وجلميــع مــا تقــدم فقــد ثبــت لــدي إدانــة‬\n     ‫املدعــى عليــة بالنصــب واالحتيــال عــن طريــق جمــع أمــوال النــاس وإيهــام‬\n     ‫أصحابها بتوظيفها مبكســب وهمي وحكمت علية لقاء ذلك بســجنه‬\n     ‫ملــدة خمــس عشــرة ســنة حتســب منهــا مــدة إيقافــه علــى ذمــة التحقيــق‬\n     ‫وجلــدة أربعــة أالف ســوط علــى دفعــات كل دفعــة خمســون ســوط ًا وبــن‬\n     ‫كل دفعــة والتــي تليهــا مــدة ال تقــل عــن خمســة أيــام وبعرضــه علــى‬\n     ‫الطرفــن قــرر جميعـ ًا عــدم القناعــة وطلبــا االســتئناف فجــرى إجابتهمــا‬\n     ‫لذلــك جــرى قفــل اجللســة يف متــام الســاعة التاســعة والنصــف صباح ـ ًا‬\n                                          ‫وبــاهلل التوفيــق حــرر يف ‪1434/02/20‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ويف يــوم االثنــن املوافــق ‪1434/8/29‬ه ـ الســاعة‬\n     ‫الواحــدة والربــع فتحــت اجللســة لــدي إنــا ‪ .........‬القاضــي باحملكمــة‬\n     ‫اجلزائيــة مبحافظــة جــدة وجــرى االطــاع علــى أوراق املعاملــة وكانــت‬\n     ‫قــد عــادت املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة وبرفقهــا‬\n     ‫قرارهــا رقــم ‪331674860‬يف ‪1434/8/23‬ه ـ باملصادقــة علــى احلكــم‬\n     ‫ونــص احلاجــة منــه (وبدراســة القــرار وصــورة ضبطــه والالئحتــن‬\n     ‫االعتراضيتــن قررنــا باألكثريــة املوافقــة علــى احلكــم واهلل املوفــق)‬\n     ‫وموقــع ومختــم مــن أصحــاب الفضيلــة أعضــاء الدائــرة اجلزائيــة األولــى‬\n     ‫وهــم كال مــن الشــيخ ‪ ........‬والشــيخ ‪........‬لــي وجهــة نظر والشــيخ ‪..........‬‬\n     ‫فجــرى تدوينــه حفظــا للواقــع وجــرى قفلهــا يف متــام الســاعة الواحــدة‬\n                 ‫والنصــف وصلــى اهلل علــى نبينــا محمــد والــه وصحبــه وســلم‪.‬‬\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد‬\n     ‫‪ -:‬فقــد جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة األولــى يف محكمــة‬\n\n\n‫‪53‬‬\n\f‫االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن‬\n‫فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة جــدة برقــم ‪33/1674860‬‬\n‫وتاريــخ ‪ 1434/7/25‬ه ـ املرفــق بهــا القــرار الشــرعي رقــم ‪34187716‬‬\n‫وتاريــخ ‪ 1434/4/14‬ه ـ الصــادر مــن فضيلــة الشــيخ ‪ .......... /‬القاضــي‬\n‫يف احملكمــة اجلزائيــة بجــدة ‪ ،‬املتضمــن دعــوى املدعــي العــام ضــد ‪/‬‬\n‫‪ ...............‬املتهــم بقضيــة نصــب واحتيــال احملكــوم فيــه مبــا دون باطنــه‪.‬‬\n‫وبدراســة احلكــم وصــورة ضبطــه والالئحتــن االعتراضيتــن قررنــا‬\n‫باألكثريــة املوافقــة علــى احلكــم ‪ ،‬واهلل املوفــق ‪ ،‬وصلــى اهلل علــى‬\n                                    ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                      ‫‪54‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"41499c81-d627-5952-8b7f-c01b2e788165","source_page_start":46,"source_page_end":54,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ad015211c3b18e198739393bf2fcb483b26efb3c64b309de9187447417649b88","normalized_text_hash":"108b4996dce919282b157fab123b936c58de4b7786fd6703ffb4b265550b9f93","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v27-p46-34187716"},{"id":"9c7738eb-bf3b-583c-b65e-34efa244b24a","document_type":"judgment","category":"judicial","subcategory":"general","title":"خيانة أمانة -استالم مبلغ وعدم توريده -عدم قبول شهادة األجير اخلاص -تفريط بعدم توثيق تسلم املبلغ مبا أمر به الشارع بالكتابة -صرف نظر عن الدعوى -إفهام املدعي بأن له مين املدعى عليه متى ما أراد .","document_number":"34289310","case_number":"3311159","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/08/6","year":"1434","subject":"خيانة أمانة -استالم مبلغ وعدم توريده -عدم قبول شهادة األجير اخلاص -تفريط بعدم توثيق تسلم املبلغ مبا أمر به الشارع بالكتابة -صرف نظر عن الدعوى -إفهام املدعي بأن له مين املدعى عليه متى ما أراد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك‪ 34289310‬تاريخه ‪1434/08/6 :‬هـ‬\n                         ‫رقم الدعوى‪3311159 :‬‬\n           ‫قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34388282‬تاريخه‪1434/12/25 :‬هـ‬\n\n\n     ‫خيانــة أمانــة ‪ -‬اســتالم مبلــغ وعــدم توريــده ‪ -‬عــدم قبــول شــهادة األجيــر‬\n     ‫اخلــاص ‪ -‬تفريــط بعــدم توثيــق تســلم املبلــغ مبــا أمــر بــه الشــارع‬\n     ‫بالكتابــة ‪ -‬صــرف نظــر عــن الدعــوى ‪ -‬إفهــام املدعــي بــأن لــه ميــن‬\n                                                     ‫املدعــى عليــه متــى مــا أراد ‪.‬‬\n\n\n\n\n     ‫‪ -1‬قــال صلــى اهلل عليــه وســلم ‪ ( :‬لــو يعطــى النــاس بدعواهــم الدعــى‬\n     ‫رجــال أمــوال قــوم ودمائهــم ولكــن البينــة علــى املدعــي واليمــن علــى‬\n                                                                       ‫مــن أنكــر ) ‪.‬‬\n        ‫‪ -2‬قوله صلى اهلل عليه وسلم ‪ ( :‬دع ما يريبك إلى ما ال يريبك )‬\n     ‫‪ -3‬قــال البهوتــي رحمــه اهلل يف الــروض املربــع ‪ ( :‬و ال تقبــل شــهادة مــن‬\n                                                  ‫يجــر لنفســه نفعـ ًا ) (‪. )603/7‬‬\n\n\n\n\n     ‫توجيــه االتهــام للمدعــى عليهمــا بخيانــة األمانــة و أخــذ مبلــغ تســعه و‬\n     ‫ســتني ألــف يــورو مــا يعــادل ثالثمائــة وتســعه وســبعني الف ـ ًا وخمســمائة‬\n     ‫ريــال ســعودي بعــد اســتالمها مــن مديــر الشــركة و عــدم توريدهــا‬\n     ‫لشــركة الصرافــة ‪ -‬حيــث تســلم مركــز الشــرطة بــاغ مــن وكيــل‬\n     ‫الشــركة التــي يعمــل بهــا املدعــى عليهمــا يتضمــن أن مديــر الشــركة‬\n\n‫‪55‬‬\n\f‫ســلم املوظفــن املدعــى عليهمــا املبلــغ املذكــور لتحويلــه حلســاب قبطــان‬\n‫الســفينة و قــام باســتدعاء الســكرتير و كتــب خطاب ـ ًا لشــركة‬\n‫الصرافــة يتضمــن تفويــض املدعــى عليهمــا بتحويــل املبلــغ املذكــور‬\n‫للقبطــان ولــم يقومــا بتحويــل املبلــغ ‪ -‬طلــب املدعــي العــام إثبــات ما أســند‬\n‫إليهمــا‪ ،‬واحلكــم عليهمــا بعقوبــة تعزيريــة ‪ -‬حضــر وكيــل الشــركة (‬\n‫املدعــي اخلــاص ) و طلــب إلــزام املدعــى عليهمــا بإرجــاع املبلــغ املذكــور‬\n‫‪ -‬أنكــر املدعــى عليهمــا مــا نســب إليهمــا ‪ -‬أحضــر املدعــي العــام و‬\n‫املدعــي اخلــاص شــاهدين موظفــن بالشــركة املدعيــة و شــهدا بصحــة‬\n‫الدعــوى ‪ -‬مت رد الشــهادة ألنهمــا أجيــران خاصــان عنــد شــركة املدعيــة‬\n‫‪ -‬قــرر املدعــي العــام و املدعــى اخلــاص أنــه ال بينــه لديهمــا ســوى مــن‬\n‫حضــر ‪ -‬جــرى إفهــام املدعــي اخلــاص بــأن لــه ميــن املدعــى عليهمــا علــى‬\n‫نفــي دعــواه ‪ -‬قــرر عــدم طلــب اليمــن ‪ -‬صــدر احلكــم بصــرف النظــر‬\n‫عــن طلــب املدعــي العــام و املدعــي اخلــاص ‪ -‬صــدق احلكم مــن محكمة‬\n                                                                     ‫االســتئناف ‪.‬‬\n\n\n\n\n‫احلمد هلل وحده وبعد فلدي أنا القاضي يف احملكمة اجلزائية مبحافظة‬\n‫جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة يف محافظــة جدة‪/‬املســاعد برقــم وتاريــخ ‪ 1433/01/04‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم وتاريــخ ‪ 1433/01/04‬ه ـ ففــي يــوم األربعــاء‬\n‫املوافــق‪ 1434/02/27‬ه ـ افتتحــت اجللســة الســاعة ‪ 09 : 00‬وفيهــا‬\n‫حضــر املدعــي العــام واملعتمــد مــن قبــل هيئــة التحقيــق واإلدعاءالعــام‬\n‫مبوجــب اخلطــاب رقــم ه ـ م ‪481/‬يف ‪1433/5/15‬ه ـ وحضــر حلضــوره‬\n                                                                                       ‫‪56‬‬\n\f     ‫املدعــى عليهمــا ‪ -1‬املدعــى عليــه األول (‪ )......‬ســعودي اجلنســية مبوجــب‬\n     ‫الســجل املدنــي رقــم (‪ ).................‬مطلــق الســراح بالكفالــة احلضوريــة‬\n     ‫‪-2‬املدعــى عليــه الثانــي (‪ )......‬ســعودي اجلنســية مبوجــب الســجل‬\n     ‫املدنــي رقم(‪،)..................‬مطلــق الســراح بالكفالــة احلضوريــة كمــا‬\n     ‫حضــر املدعــي باحلــق اخلــاص وكالــة املدعــو‪ ................. /‬ســعودي‬\n     ‫اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )...................‬بالوكالــة‬\n     ‫الشــرعية عــن (شــركة‪ ).....................‬مبوجــب الوكالــة رقــم ( ‪).......‬‬\n     ‫يف ‪1433/01/18‬ه ـ جلــد ( ‪ )3662‬والصــادرة مــن كتابــة عــدل شــمال‬\n     ‫جــدة وقــال املدعــي العــام يف دعــواه أنــه بتاريــخ ‪1432/10/28‬ه ـ تســلم‬\n     ‫مركــز شــرطة البلــد بــاغ مــن الوكيــل الشــرعي عــن شــركة ‪/...........‬‬\n     ‫(ســعودي اجلنســية) وأفــاد بأنــه يف متــام الســاعة العاشــرة صباحـ ًا مــن يــوم‬\n     ‫األربعــاء املوافــق ‪1432/10/23‬ه ـ قــام مديــر الشــركة‪ ... /‬باســتدعاء‬\n     ‫املوظفــن بالشــركة املدعــى عليهمــا األول والثانــي وســلمهما(‪)69000‬‬\n     ‫مبلــغ تســعة وســتون ألــف يــورو وطلــب منهمــا حتويــل املبلــغ حلســاب‬\n     ‫قبطــان الناقلــة (‪ )...........‬الســيد‪ /‬وقــام باســتدعاء الســكرتير‪/‬‬\n     ‫‪ ...‬مصــري اجلنســية وطلــب منــه كتابــة خطــاب لشــركة للصرافــة‬\n     ‫متضمن ـ ًا تفويــض املدعــى عليهمــا بتحويــل املبلــغ حلســاب القبطــان‬\n     ‫‪ /‬ويف ذات اليــوم قــام املديــر‪ ... /‬باالتصــال بهمــا وســألهما عــن املبلــغ‬\n     ‫فذكــرا انهمــا قامــا بتحويلــه وســيحضران ســند اإليصــال كــون دوام‬\n     ‫الشــركة انتهــى ويف يــوم األحــد ‪1432/10/27‬ه ـ مت االتصــال عليهمــا‬\n     ‫وســألهما عــن املبلــغ وعــن ســند تســليمه فأفــادا بأنهمــا لــم يســتلما أي‬\n     ‫مبلــغ بضبــط شــهادة املدعــو‪( /‬مصــري اجلنســية) أفــاد بأنــه يــوم األربعــاء‬\n     ‫املوافــق ‪1432/10/23‬ه ـ طلــب منــه املديــر حتريــر كتــاب لشــركة‬\n\n\n‫‪57‬‬\n\f‫‪ ............‬متضمن ـ ًا تفويــض املدعــى عليهمــا املذكــوران أعــاه بتحويــل‬\n‫مبلــغ تســعة وســتون ألــف يــورو حلســاب القبطــان ‪............ /‬فقــام بتحريــر‬\n‫الكتــاب وبعــد ذلــك حضــر املدعــى عليهمــا ملكتــب املديــر وســلمهما‬\n       ‫الكتــاب واملبلــغ وكان الوكيــل الشــرعي للشــركة حاضــراً‪..‬‬\n‫وقــد خلــص التحقيــق إلــى توجيــه االتهــام للمدعــى عليهمــا‪ /‬بخيانــة‬\n‫األمانــة وأخــذ مبلــغ تســعة وســتون ألــف يــورو مــا يعــادل ثالثمائــة وتســعة‬\n‫وســبعون ألــف وخمســمائة ريــال ســعودي بعــد اســتالمها مــن مديــر‬\n‫الشــركة وعــدم توريدهــا لشــركة الصرافــة وذلــك لألدلــة والقرائــن‬\n‫املســرودة مبلــف القضيــة وببحــث ســوابق املدعــى عليهمــا عثــر لــأول‬\n‫علــى ســابقة شــرب املســكر وقيــادة الســيارة وهــو بحالــة ســكر ولــم‬\n‫يعثــر للثانــي علــى ســوابق مســجله حتــى تاريخــه وحيــث أن مــا أقدمــا‬\n‫عليــه املدعــى عليهمــا املذكــوران وهمــا بكامــل أهليتهمــا املعتبــرة‬\n‫شــرع ًا فعــل محــرم ومعاقــب عليــه شــرع ًا لــذا اطلــب إثبــات مــا أســند‬\n‫إليهمــا واحلكــم عليهمــا بعقوبــة تعزيريــة لقــاء ذلــك وبتــاوة ماجــاء يف‬\n‫الئحــة املدعــي العــام علــى املدعــى عليهمــا أجابــا بقولهمــا بــأن ماذكــره‬\n‫املدعــي العــام مــن خيانتنــا لألمانــة وأخــذ مبلــغ قــدره تســعة وســتون ألــف‬\n‫( ‪ )69000‬يــورو مــا يعــادل ثالثمائــة وتســعة وســبعون ألــف وخمســمائة‬\n‫(‪ )379500‬ريــال وأننــا لــم نقــم بتوريدهــا لشــركة الصرافــه فهــذا‬\n‫غيــر صحيــح وفيهــا حضــر املدعــي باحلــق اخلــاص وكالــة وأدعــي قائــا‬\n‫أن املدعــى عليهمــا قامــا بخيانــة األمانــة وأخــذ مبلــغ قــدره ثالثمائــة‬\n‫وتســعة وســبعون ألــف وخمســمائة ‪379500‬ريــال مــن شــركة موكلــي‬\n‫ولــم يــوردوا هــذا املبلــغ الــذي أخــذاه إلــى شــركة الصرافــة لــذا أطلــب‬\n‫إلزامهــم بإرجــاع هــذا املبلــغ كامــا وقــدره ثالثمائــة وتســعة وســبعون‬\n\n\n                                                                                      ‫‪58‬‬\n\f                                     ‫ألــف وخمســمائة ‪379500‬ريــال هــذه دعــواي‬\n     ‫وبســؤال املدعــي باحلــق اخلــاص واملدعــي العــام ألديكمــا بينــه علــى‬\n     ‫دعواكمــا أجــاب املدعــي باحلــق اخلــاص وكالــة قــال أطلــب إمهالــي إلــى‬\n     ‫جلســة الحقــة وبــاهلل التوفيــق احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء‬\n     ‫املوافــق‪ 1434/05/14‬ه ـ افتتحــت اجللســة الســاعة العاشــرة صباح ـ ًا‬\n     ‫وفيهــا حضــر املدعــي العــام وحضــر حلضــوره املدعــى عليهمــا وحضــر‬\n     ‫حلضورهمــا وكيــل املدعــي يف احلــق اخلــاص ســعودي اجلنســية بالســجل‬\n     ‫املدنــي رقــم ‪..........‬ف‪ .......‬بالوكالــة رقــم ‪ ......‬يف ‪1433/1/18‬ه ـ جلــد‬\n     ‫‪ 3662‬خــاص ‪/34/405‬خ الصــادرة مــن كتابــة عــدل الثانيــة بجنــوب‬\n     ‫محافظــة جــدة بســؤال عمــا طلــب املهلــة مــن أجلــه أحضــر املدعــي‬\n     ‫للشــهادة وأدائهــا املدعــو ‪ ..............‬مصــري اجلنســية باإلقامة رقــم ‪...........‬‬\n     ‫ولــدى استشــهاده شــهد بقولــه أشــهد هلل تعالــى يف يــوم األربعــاء املوافــق‬\n     ‫‪2011/9/21‬م بأنــه اتصــل علــى صاحــب الشــركة وطلــب منــي عمــل‬\n     ‫تفويــض باســم لــدى شــركة ‪ ....‬بتحويــل مبلــغ تســعة وســتون ألــف يــورو‬\n     ‫( ‪ ) 69000‬حلســاب كاتــن يعمــل عنــده اســمه ثــم عملــت التفويــض‬\n     ‫وســلمته ملديــر الشــركة كمــا طلــب وكان يتواجــد معــه ورأيتــه وهــو‬\n     ‫يعــد مبالــغ ماليــه وقــال هــذه تســعة وســتون ألــف يــورو( ‪ ) 69000‬ثــم‬\n     ‫ســلم كامــل هــذا املبلــغ لــدى املدعــو وبعــد ذلــك وقــع مديــر الشــركة‬\n     ‫التفويــض ومــن ثــم أعطانــي الورقــة لتصويرهــا وبعــد تصويــر ورقــة‬\n     ‫التفويــض ســلمتها للمديــر والــذي بــدوره أعطاهــا ل و هــذا مالــدي أشــهد‬\n     ‫بــه هلل تعالــى ثــم جــرى مناقشــة الشــاهد مــن قبــل املدعــي عليــه طارحـ ًا‬\n     ‫للشــاهد ســؤال يف أي ســاعة مت االجتمــاع بينــي وبــن املديــر كمــا تزعــم‬\n     ‫؟ أجــاب الشــاهد بقولــه يف متــام الســاعة العاشــرة صباحـ ًا هكــذا أجــاب‬\n\n\n‫‪59‬‬\n\f‫كمــا حضــر للشــهادة املدعــو ســعودي اجلنســية بالســجل املدنــي رقــم‬\n‫(‪)...............‬وشــهد بقولــه أشــهد هلل تعالــى بــأن يف يــوم األربعــاء املوافــق‬\n‫‪1432/10/23‬ه ـ يف متــام الســاعة التاســعة صباح ـ ًا تقريب ـ ًا كنــت‬\n‫متواجــد مــع مديــر شــركة وكان يتواجــد معنــا و وذكــر لهمــا بأنــه‬\n‫يريــد حتويــل مبلــغ قــدره تســعة وســتون ألــف يــورو ( ‪ ) 69000‬يف حســاب‬\n‫كابــن مــن جنســية اليونانيــة يعمــل عنــده برتبــة قبطــان ثــم اتصــل مديــر‬\n‫الشــركة علــى أحــد موظفيــه وطلــب منــه أن يحــرر لــه خطاب ـ ًا يتضمــن‬\n‫تفويــض وللقيــام بتحويــل املبلــغ املذكــور حلســاب الكابــن لــدي‬\n‫شــركة‪ ..........‬للصرافــة وبعــد ذلــك قــام مديــر الشــركة بإخــراج املبلــغ‬\n‫وقــام بعــده ومــن ثــم ســلمه للمدعــى عليهمــا وأعطــاه خطــاب التفويــض‬\n‫هــذا مالــدي وأشــهد بــه هلل تعالــى وبعــرض ماجــاء يف شــهادة الشــاهدين‬\n‫علــى املدعــى عليهمــا قــرر بقولهمــا بــأن ماجــاء يف شــهادة الشــاهدين‬\n‫ا وأن الشــاهدين أحدهمــا يعمــل عنــد‬        ‫كلــه غيــر صحيــح جملــة وتفصيـ ً‬\n‫املدعــي بالشــركة واألخــر وكيــل شــرعي عــن الشــركة وبينــه عالقــة‬\n‫مصاهــره لــذا فأننــا نطعــن يف هــذه الشــهادة هكــذا قــررا كمــا‬\n‫أضــاف املدعــى عليــه بأنــي يف يــوم األربعــاء املوافــق ‪1432/10/23‬ه ـ‬\n‫كنــت يف مــن الســاعة الثامنــة صباحـ ًا إلــى الثانيــة عشــرة ظهــر ًا داخــل‬\n‫مينــاء جــدة اإلســامي وعنــدي مــا يثبــت ذلــك ومختــم مــن قبــل ســاح‬\n‫ا بأننــي يف ذات اليــوم‬   ‫احلــدود كمــا أضــاف املدعــى عليــه الثانــي قائ ـ ً‬\n‫كنــت متواجــد يف اجلــوازات ولــم أكــن متواجــد يف الشــركة وعنــدي‬\n‫مايثبــت ذلــك ثــم ســألت املدعــى عليهمــا ألديكمــا بينــة علــى ذلــك قــاال‬\n‫نطلــب إمهالنــا إلــى جلســة الحقــة فأجبتهمــا لطلبهمــا وإلــى ذلــك رفعــت‬\n‫اجللســة إلــى يــوم األحــد ‪1434/5/26‬ه ـ الســاعة احلاديــة عشــر والنصــف‬\n\n\n                                                                                         ‫‪60‬‬\n\f     ‫وكان ختــام اجللســة يف متــام الســاعة العاشــرة والنصــف وبــاهلل التوفيــق‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد املوافــق‪ 1434/05/26‬ه ـ‬\n     ‫افتتحــت اجللســة الســاعة احلاديــة عشــر والنصــف وفيهــا حضــر املدعــي‬\n     ‫العــام وحضــر حلضــور املدعــى عليهمــا وحضــر حلضورهــم املدعــي باحلــق‬\n     ‫اخلــاص وكالــة وبســؤال املدعــى عليــه عمــا طلــب املهلــة مــن أجلــه‬\n     ‫أبــرز تصريــح إبحــار مــن املديريــة العامــة حلــرس احلــدود املذيلــة باخلتــم‬\n     ‫الرســمي مــن قبــل وحــدة أمــن مينــاء جــدة اإلســامي واملوقــع مــن قبــل‬\n     ‫معــد التصريــح رقيــب أول وكان ســاعة الدخــول يف متــام الســاعة الثامنــة‬\n     ‫والنصــف صباحـ ًا إلــى الثانيــة عشــر والنصــف ظهــر ًا كمــا أبــرز املدعــى‬\n     ‫عليــه ورقــة مــن اجلــوازات الســعودية بتاريــخ ‪1432/10/23‬ه ـ املتضمنــة‬\n     ‫مراجعتــه للجــوازات وبســؤال املدعــى عليــه عــن ســاعة تواجــده يف مقــر‬\n     ‫ا بأنــي تواجــدت يف متــام الســاعة الثامنــة والنصــف‬    ‫اجلــوازات أجــاب قائـ ً‬\n     ‫صباحـ ًا إلــى الســاعة الثانيــة عشــر ظهــر ًا تقريبـ ًا ثــم عــدت إلــى الشــركة‬\n     ‫بعــد الظهــر وأخــذت معاملــة وقمــت إجنازهــا يف متــام الســاعة الثانيــة‬\n     ‫ظهــر ًا وأرجعتهــا إلــى الشــركة هكــذا أجــاب وبعــرض ذلــك علــى‬\n     ‫املدعــى عليــه وكالــة قــرر بقولــه صحيــح أن املدعــى عليــه قــد تواجــد‬\n     ‫يف البحــارة يف متــام الســاعة الثامنــة والنصــف تقربيـ ًا ولكنــه انتهــى مــن‬\n     ‫البحــارة يف متــام الســاعة العاشــرة إال ربــع تقريبـ ًا ومــا ذكــر يف تصريــح‬\n     ‫ســاح احلــدود بأنــه قــد خــرج مــن البحــارة يف متــام الســاعة الثانيــة عشــر‬\n     ‫والنصــف فهــذا غيــر صحيــح كمــا قــرر قائــا بــأن مــا ذكــره املدعــى‬\n     ‫عليــه بأنــه كان متواجــد يف اجلــوزات يف متــام الســاعة الثامنــة والنصــف‬\n     ‫للقيــام بإجنــاز معاملــة وأنــه عــاد يف الظهــر فهــذا صحيــح وهــذا يــدل بأنــه‬\n     ‫متناقــض يف أقوالــه حيــث أنــه أنكــر تواجــده يف جــده حيــث ذكــر أنــه‬\n\n\n‫‪61‬‬\n\f‫متواجــد يف اخلبــر يــوم الثالثــاء ويف الدمــام األربعــاء ومرفــق ذلــك يف ملف‬\n‫التحقيــق هكــذا قــرر وبســؤال املدعــي العــام واملدعــي باحلــق اخلــاص‬\n‫وكالــة ألديكــم زيــادة بينــة قــرر املدعــي العــام ليــس لــدي إال مــا أرفــق‬\n‫باملعاملــة كمــا قــرر املدعــي باحلــق اخلــاص وكالــة بــأن عنــدي بينــة تديــن‬\n‫املدعــى عليــه بأنــه عــاد مــن البحــارة يف متــام الســاعة العاشــرة إال ربــع‬\n‫صباح ـ ًا تقريب ـ ًا وأطلــب إمهالــي إلــى جلســة الحقــة فأجبتــه لطلبــه ومت‬\n‫تأجــل اجللســة إلــى يــوم االثنــن ‪1434/06/7‬ه ـ يف متــام الســاعة ‪30:11‬‬\n‫وكان ختــام اجللســة يف متــام الســاعة الثانيــة عشــر ظهــر ًا وبــاهلل التوفيــق‬\n‫‪،‬احلمــد هلل وحــده وبعــد ففــي يــوم اإلثنــن املوافــق ‪ 1434/06/07‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 11.30‬وفيهــا حضــر املدعــي وكالــه وبســؤاله‬\n‫عمــا طلــب املهلــة مــن أجلــه أحضــر للشــهادة وأدائهــا املدعــو ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ 0...........‬ولــدى استشــهاده شــهد‬\n‫قائــا اشــهد اهلل تعالــى بــأن املدعــو قــد انتهــى عملــه مــن البحــارة يف‬\n‫متــام الســاعة العاشــرة إال ربــع وقــد اخبرنــي بذلــك شــخص ثــم ذهــب‬\n‫الــى الشــركة يف متــام الســاعة العاشــر صباحــا تقريبــا ثــم اتصــل علــي‬\n‫للذهــاب إلــى املدرســة الحضــار ابنــه حيــث أنــي أنــا املشــرف واملســؤول‬\n‫عليــه يف الشــركة ثــم جــرى ســؤال الشــاهد هــل رأيتــه يف ذلــك اليــوم يف‬\n‫الشــركة أجــاب قائــا بأنــي لــم اره هكــذا أجــاب ثــم ســالت املدعــي‬\n‫باحلــق اخلــاص وكالــة ألديــك زيــادة بينــه قــال بينتــي ان املدعــى عليهمــا‬\n‫قــد تغيبــا بعــد احلادثــة يــوم اخلميــس ‪1432/10/14‬ه ـ ويــوم اجلمعــة ويــوم‬\n‫الســبت ويــوم األحــد دون عــذر مســبق وعنــدي قرينــة بــأن املدعــى عليــه‬\n‫قــد كــذب علــى جهــة التحقيــق بــان لــم يذكــر لهــم بــان لديــه ســابقة‬\n‫شــرب مســكر وبســؤاله الديــك زيــادة بينــه غيــر ذلــك قــرر بقولــه ليــس‬\n\n\n                                                                                      ‫‪62‬‬\n\f     ‫لــدي إال مــا جــاء يف بيناتــي الســابق ذكرهــا هكــذا قــرر ثــم جــرى‬\n     ‫ســؤال جميــع أطــراف الدعــوى هــل عندكــم مــا تريــدون إضافتــه قــرروا‬\n     ‫جميعــا بقولهــم ال نريــد إضافــة أي شــيء ثــم قــررت قفــل بــاب املرافعــة‬\n     ‫اســتنادا للمــادة السادســة والســتني مــن نظــام املرافعــات الشــرعية‬\n     ‫ولوائحهــا التنفيذيــة ولتأمــل مــا ســبق رفعــت اجللســة وأقفلــت يف متــام‬\n                                                   ‫الســاعة ‪ 12.00‬وبــاهلل التوفيــق ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد ففــي يــوم الســبت املوافــق ‪ 1434/08/06‬ه ـ‬\n     ‫افتتحــت اجللســة الســاعة ‪ 11.00‬وفيهــا حضــر املدعــي العــام وحضــر‬\n     ‫ـاء علــى مــا ســبق‬  ‫حلضــوره املدعــى عليهمــا واملدعــي باحلــق اخلــاص فبنـ ً‬\n     ‫مــن الدعــوى وجوابهــا وملــا جــاء يف دعــوى املدعــي باحلــق اخلــاص وكالــة‬\n     ‫واملدعــي العــام مــن أن املدعــى عليهمــا قــد خانــا األمانــة بأخــذ مبلــغ‬\n     ‫قــدره تســعة وســتون ألــف يــورو (‪ )69000‬مــن الشــركة موكلتــه ومبــا‬\n     ‫ا‬‫أن املدعــى عليهمــا قــد أنكــرا مــا جــاء يف الدعويــن جملــة وتفصي ـ ً‬\n     ‫ومبــا أن املدعــي العــام واملدعــي باحلــق اخلــاص لــم يأتيــا ببينــة موصلــة‬\n     ‫علــى دعواهمــا وحيــث أن غايــة مــا اســتندوا إليــه إمنــا هــو شــهادة‬\n     ‫الشــاهدين وأقوالهمــا مبلــف التحقيــق ولــم جندهــا موصلــة ومثبتــة‬\n     ‫لإلدانــة عليهمــا ومبــا أن املدعــى عليهمــا قــد طعنــا يف شــهادة الشــاهدين‬\n     ‫كونهمــا يعمــان يف شــركة املدعــي باحلــق اخلــاص وألن مــا طعنــا‬\n     ‫بــه مقبــول شــرع ًا وموافــق ملــا قــرره مــن أن شــهادة األجيــر اخلــاص ال‬\n     ‫تقبــل ألنهــا مظنــة أن يكــون يف جــر املنفعــة لصاحبهــا قــال البهوتــي‬\n     ‫رحمــه اهلل تعالــى يف الــروض املربــع((وال تقبــل شــهادة مــن يجــر لنفســه‬\n     ‫نفعـاً))ج‪ 603/7‬وألن املدعــي قــد فــرط بعــدم حفــظ أموالــه مبــا أمــر بــه‬\n     ‫الشــارع مــن الكتابــة ســيما وأن املبلــغ املدعــى بــه كبيــر ويبعــد اعطائــه‬\n\n\n‫‪63‬‬\n\f‫لشــخص دون توثيــق وألن املدعــى عليهمــا قــد دفعــا بعــدم وجودهمــا‬\n‫مبقــر الشــركة حينئــذ وملــا قدمــوه مــن بينــة علــى ذلــك وألن املدعــي‬\n‫باحلــق اخلــاص لــم يثبــت كذبهمــا علــى عــدم التواجــد يف الشــركة ومبــا‬\n‫أن دعــوى خيانــة األمانــة حتتــاج إلــى أدلــة قويــة ودامغــة تقــوي بعضهــا‬\n‫بعض ـ ًا ولعــدم وجــود ثمــة ســابقه علــى املدعــى عليهمــا مــن ذات التهمــة‬\n‫املنســوبة لهمــا ولقــول النبــي صلــى اهلل عليــه وســلم ((لــو يعطــى النــاس‬\n‫بدعواهــم الدعــى رجــال أمــوال قــوم ودماءهــم ولكــن البينــة علــى‬\n‫املدعــي واليمــن علــى مــن أنكــر)) ولقولــه صلــى اهلل عليــه وســلم ((دع‬\n‫مــا يريبــك إلــى مــا ال يريبــك)) ومــن أجــل ذلــك كلــه لــم يثبــت لــدي‬\n‫إدانــة املدعــى عليهمــا مبــا نســب إليهمــا مــن تهمــة وقــررت علــى إثــر ذلــك‬\n‫صــرف النظــر عــن دعــوى املدعيــن باحلــق العــام واخلــاص وأخليــت ســبيل‬\n‫املدعــى عليهمــا وبذلــك كلــه حكمــت وأفهمــت املدعــي باحلــق اخلــاص‬\n‫وكالــة بــأن لــه ميــن املدعــى عليهمــا علــى نفــي دعــواه فهــم ذلــك ثــم قــرر‬\n‫بقولــه ارفــض ميــن املدعــى عليهمــا فأفهمتــه بأنــه علــى حقــه يف طلــب‬\n‫اليمــن متــى مــا أرادهــا وبعــرض احلكــم علــى املدعــى عليهمــا قــررا‬\n‫القناعــة بــه وبعرضــه علــى املدعــي باحلــق اخلــاص وكالــه وعلــى املدعــي‬\n‫العــام قــررا عــدم القناعــة بــه طالبــن اســتئناف احلكــم فأفهمتهمــا بــأن‬\n‫لهمــا مــدة عشــرة أيــام الســتالم صــورة مــن قــرار احلكــم وبعــد ذلــك لهمــا‬\n‫مــدة ثالثــون يومـ ًا لتقــدمي الئحتهمــا االعتراضيــة فــإن مضــت هــذه املــدة‬\n‫ولــم يقدمــا الالئحــة فــان حــق املدعــي باحلــق اخلــاص يســقط ويكتســب‬\n‫احلكــم القطعيــة بينمــا ســيتم رفــع كامــل املعاملــة حملكمــة االســتئناف‬\n‫بعــد خمســة وأربعــن يومـ ًا مــن تاريــخ النطــق باحلكــم هــذا فيمــا يخــص‬\n‫املدعــي العــام اســتنادا للمــادة اخلامســة والتســعني بعــد املائــة مــن نظــام‬\n\n\n                                                                                        ‫‪64‬‬\n\f     ‫اإلجــراءات اجلزائيــة وكان ختــام اجللســة يف متــام الســاعة ‪ 11.30‬وبــاهلل‬\n     ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                       ‫حــرر يف ‪ 1434/08/06‬هــ‪.‬‬\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‪ :‬فقــد‬\n     ‫جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة الثالثــة مبحكمــة االســتئناف‬\n     ‫مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة إلينــا شــفع‬\n     ‫خطــاب فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة جــدة رقــم‬\n     ‫‪ 3327731‬وتاريــخ ‪1434/12/2‬ه ـ املشــتملة علــى القــرار الصــادر مــن‬\n     ‫فضيلــة الشــيخ‪ /‬القاضــي باحملكمــة اجلزائيــة مبحافظــة جــدة املــؤرخ يف‬\n     ‫‪1434/8/6‬ه ـ واملســجل بعــدد ‪ ، 34289310‬املتضمــن دعــوى املدعــي‬\n     ‫العــام واملدعــي باحلــق اخلــاص‪ /‬ضــد‪ /‬املدعــى عليــه ورفيقــه املتهمــن‬\n     ‫بخيانــة األمانــة احملكــوم فيــه مبــا ّدون بباطــن القــرار وبدراســة القــرار‬\n     ‫وصــورة ضبطــه والئحتــه االعتراضيــة تقــررت املوافقــة علــى احلكــم‬\n     ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪65‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"41499c81-d627-5952-8b7f-c01b2e788165","source_page_start":55,"source_page_end":65,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"6d1335123f94511ef6f6297709daa2001fa4b46a35b1084fe34c614d1147040e","normalized_text_hash":"89c7a8ad4b7c722110beca84d942f9f1da605729f2dd7ac0974270f7a7d42a87","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v27-p55-34289310"},{"id":"2f97fe2a-600c-5480-9377-1bf307560b95","document_type":"judgment","category":"judicial","subcategory":"general","title":"خيانة أمانة -استيالء عمال على إعاشة السجناء -اإلقرار باالستيالء على اإلعاشة -التعزير بالسجن واجللد على دفعات مرتن منها أمام مقر عمل املدعى عليهم ،مع التوصية باإلبعاد.","document_number":"34279674","case_number":"34334605","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف وبرفقها القرار","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/07/25","year":"1434","subject":"خيانة أمانة -استيالء عمال على إعاشة السجناء -اإلقرار باالستيالء على اإلعاشة -التعزير بالسجن واجللد على دفعات مرتن منها أمام مقر عمل املدعى عليهم ،مع التوصية باإلبعاد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34279674 :‬تاريخه‪1434/07/25 :‬هـ‬\n                    ‫رقم الدعوى‪34334605 :‬‬\n       ‫قرار التصديق من محكمة االستئناف‪:‬‬\n         ‫‪ 34323910‬تاريخه ‪1434/9/22 :‬هـ‬\n\n\n ‫خيانــة أمانــة ‪ -‬اســتيالء عمــال علــى إعاشــة الســجناء ‪ -‬اإلقــرار‬\n ‫باالســتيالء علــى اإلعاشــة ‪ -‬التعزيــر بالســجن واجللــد علــى دفعــات‬\n ‫مرتــن منهــا أمــام مقــر عمــل املدعــى عليهــم ‪ ،‬مــع التوصيــة باإلبعــاد‪.‬‬\n\n\n\n\n                  ‫‪ -‬قوله تعالى‪( :‬والذين هم ألماناتهم وعهدهم راعون) ‪.‬‬\n ‫‪ -‬قولــه صلــى اهلل عليــه وســلم ‪ ( :‬ال إميــان ملــن ال أمانــة لــه وال ديــن‬\n ‫ملــن ال عهــد لــه) أخرجــه احمــد مــن حديــث أنــس رضــي اهلل عنــه كمــا‬\n ‫أخرجــه ابــن أبــي شــيبه يف املصنــف والبيهقــي والبــزار وصححــه ابــن‬\n                                                                         ‫حبــان‪.‬‬\n ‫‪ -‬قولــه صلــى اهلل عليــه وســلم ‪ ( :‬ال تســتقيم أمانــة رجــل حتــى يســتقيم‬\n          ‫لســانه وال يســتقيم لســانه حتى يســتقيم قلبه) أخرجه احمد‪.‬‬\n ‫‪ -‬قولــه صلــى اهلل عليــه وســلم ‪ ( :‬أربــع إذا كــن فيــك فــا عليــك‬\n ‫مــا فاتــك مــن الدنيــا صــدق احلديــث وحفــظ األمانــة وحســن اخللــق‬\n      ‫وعفــة املطعــم ) أخرجــه احمــد والبخــاري واحلاكــم والبيهقــي ‪.‬‬\n\n\n\n\n                                                                                    ‫‪66‬‬\n\f     ‫انتهــى التحقيــق إلــى توجيــه االتهــام للمدعــى عليهــم (ثالثــة مقيمــن)‬\n     ‫يعملــون بإعاشــة الســجناء بأحــد الســجون‪ ،‬بخيانــة األمانــة واالســتيالء‬\n     ‫علــى عــدد خمســة عشــر كرتــون دجــاج ‪ ،‬وخمســة كراتــن حلــم مفــروم‬\n     ‫مــن إعاشــة ســجناء أحــد الســجون ‪ ،‬بالبحــث ســوابقهم اتضــح عــدم‬\n     ‫وجــود ســوابق مســجلة عليهــم ‪ ،‬طلــب املدعــي العــام إثبــات إدانتهــم‬\n     ‫مبــا أســند إليهــم واحلكــم عليهــم بعقوبــة تعزيريــة مشــددة ‪ -‬بعــرض‬\n     ‫دعــوى املدعــي العــام علــى املدعــى عليهــم بواســطة املترجــم أجــاب‬\n     ‫كل واحــد منهــم بإنكارهــا ودفــع بأنــه أخــرج اإلعاشــة املطلوبــة وقــد‬\n     ‫زاد منهــا الكميــة املذكــورة ثــم أرجعهــا جميعــا للثالجــة ولــم يســتول‬\n     ‫عليهــا ‪ ،‬جــرى االطــاع علــى إقــرارات املدعــى عليهــم املصدقــة شــرعا‪،‬‬\n     ‫وبعرضهــا عليهــم صادقــوا عليهــا ‪ ،‬ثــم صــادق املدعــى عليهــم علــى‬\n     ‫دعــوى املدعــي العــام وقــرروا توبتهــم وندمهــم ‪ -‬نظــر ًا ملصادقــة املدعــى‬\n     ‫عليهــم علــى دعــوى املدعــي العــام وال عــذر ملــن أقــر ومبــا أن هــذا الفعــل‬\n     ‫مشــن وخيانــة لألمانــة‪ ،‬لــذا ثبتــت إدانــة املدعــى عليهــم مبــا أســند إليهــم‬\n     ‫ومت احلكــم بســجن كل واحــد مــن املدعــى عليهــم مــدة عشــرة أشــهر‪،‬‬\n     ‫وجلــده مائتــي جلــدة مفرقــه علــى أربــع مــرات يكــون منهــا مرتــن أمــام‬\n     ‫مقــر عملهــم الســابق ليكــون ذلــك عبرة لآلخرين مــع التوصية بإبعادهم‬\n     ‫جميعــا عــن هــذه البــاد وعــدم الســماح لهــم بالدخــول مــره أخــرى ســوى‬\n     ‫مــا يخــص نظــام احلــج والعمــرة ‪ ،‬بعــرض احلكــم علــى املدعــى عليهــم‬\n     ‫قنعــوا بــه وأمــا املدعــي العــام فقــرر اعتراضــه ويكتفــي بالئحــة الدعــوى‬\n     ‫عــن الئحــة االعتــراض‪ ،‬وبعــد رفــع احلكــم حملكمــة االســتئناف متــت‬\n                                                                        ‫املصادقــة عليــه ‪.‬‬\n‫‪67‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بالريــاض برقــم ‪ 34334605‬وتاريــخ ‪ 1434/07/18‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 341743832‬وتاريــخ ‪1434/07/18‬ه ـ ففــي يــوم‬\n‫االثنــن املوافــق ‪1434/07/24‬ه ـ افتتحــت اجللســة الســاعة ‪01 : 30‬‬\n‫للنظــر يف الدعــوى املرفوعــة مــن املدعــي العــام ضــد ‪ .....‬ورفقــاه بدعــوى‬\n‫خيانــة األمانــة‪ ،‬وفيهــا حضــر املدعــي العــام ‪ .....‬وادعــى علــى احلاضريــن‬\n                                                                          ‫معــه‪:‬‬\n‫‪ 35..... /1‬ســنة هنــدي اجلنســية إقامــة رقــم (‪ ).....‬موقــوف بتاريــخ‬\n‫‪1434/4/10‬ه ـ وأحيــل إلــى ســجن امللــز بأمــر التوقيــف رقــم (‪).....‬‬\n                                                     ‫بتاريــخ ‪1434/4/30‬ه ـ ‪.‬‬\n‫‪ 32..... /2‬ســنة هنــدي اجلنســية اقامــة رقــم (‪ ).....‬موقــوف بتاريــخ‬\n‫‪1434/4/10‬ه ـ واحيــل إلــى ســجن امللــز بأمــر التوقيــف رقــم (‪).....‬‬\n                                                   ‫بتاريــخ ‪1434/4/30‬ه ـ ‪.‬‬\n‫‪ 33...../3‬ســنة بنجالديشــي اجلنســية إقامــة رقــم (‪ ).....‬موقــوف بتاريــخ‬\n‫‪1434/4/10‬ه ـ وأحيــل إلــى ســجن امللــز بأمــر التوقيــف رقــم (‪).....‬‬\n                                                    ‫بتاريــخ ‪1434/4/30‬ه ـ ‪.‬‬\n‫قائــا يف دعــواه‪ :‬أنــه بتاريــخ ‪1434/4/1‬ه ـ ورد خطــاب مديــر شــعبة‬\n‫إصالحيــة احلائــر رقــم ‪ 311‬املتضمــن قيــام العمــال الذين يعملون بإعاشــة‬\n‫ســجناء إصالحيــة احلائــر املدعــى عليهــم بســرقة عــدد (‪ )15‬كرتــون‬\n                                    ‫دجــاج وعــدد (‪ )5‬كرتــون حلــم مفــروم‪.‬‬\n\n                                                                                   ‫‪68‬‬\n\f     ‫جــرى مواجهــة األول بعضــو إعاشــة الســجن العريــف‪ ..... /‬وذلــك حيــال‬\n     ‫إنكار األول بعد إعادة عدد خمســة عشــر كرتون دجاج وعدد خمســة‬\n     ‫كراتــن حلــم مفــروم وقيــام العضــو بوضــع عالمــات علــى الكراتــن‬\n     ‫التــي مت اســتخراجها مــن الثالجــة ومبواجهتهمــا ببعضهمــا البعــض عــدل‬\n     ‫األول عــن أقوالــه واعتــرف مبــا ذكــره عضــو اإلعاشــة وانــه فعــا أعــاد‬\n                                               ‫تلــك الكميــة مــرة أخــرى للثالجــة ‪.‬‬\n     ‫جــرى مواجهــة الثانــي بعضــو إعاشــة الســجن العريــف‪ ..... /‬وذلــك‬\n     ‫حيــال إنــكار األول بعــد إعــادة عــدد خمســة عشــر كرتــون دجــاج‬\n     ‫وعــدد خمســة كراتــن حلــم مفــروم وقيــام العضــو بوضــع عالمــات علــى‬\n     ‫الكراتــن التــي مت اســتخراجها مــن الثالجــة ومبواجهتهمــا ببعضهمــا‬\n     ‫البعــض عــدل الثانــي عــن اقوالــه واعتــرف مبــا ذكــره عضــو اإلعاشــة‬\n                         ‫وأنــه فعــا أعــاد تلــك الكميــة مــرة أخــرى للثالجــة ‪.‬‬\n     ‫جــرى مواجهــة الثالــث بعضــو إعاشــة الســجن العريــف ‪ ..... /‬وذلــك‬\n     ‫حيــال إنــكار األول بعــد إعــادة عــدد خمســة عشــر كرتــون دجــاج‬\n     ‫وعــدد خمســة كراتــن حلــم مفــروم وقيــام العضــو بوضــع عالمــات علــى‬\n     ‫الكراتــن التــي مت اســتخراجها مــن الثالجــة ومبواجهتهمــا ببعضهمــا‬\n     ‫البعــض عــدل الثالــث عــن أقوالــه واعتــرف مبــا ذكــره عضــو اإلعاشــة‬\n                           ‫ا أعــاد تلــك الكميــة مــرة أخــرى للثالجــة ‪.‬‬  ‫وأنــه فع ـ ً‬\n     ‫وبســماع شــهادة الطباخ ‪ ..... /‬ســوداني اجلنســية أفاد بأن الثاني والثالث‬\n     ‫اعــادا (‪ )15‬كرتــون دجــاج مــن وجبــة العشــاء وبتاريــخ ‪1434/4/1‬ه ـ‬\n            ‫وعــدد (‪ )5‬كرتــون حلــم مفــروم واودعوهــا الثالجــة امــام ناظريــه ‪.‬‬\n     ‫وبســماع أقــوال ‪..... /‬يعمــل برتبــة عريــف بشــعبة إصالحيــة احلائــر‬\n     ‫وعضــو جلنــة اإلعاشــة أفــاد أنــه خــال اســتالمه علــى اإلعاشــة اخلاصــة‬\n\n\n‫‪69‬‬\n\f‫بالســجناء وبإخــراج مــا يتــم طبخــه مــن الدجــاج واللحــم املفــروم‬\n‫مــن املســتودع العائــد لشــركة ‪ .....‬واســتالمه مــن قبلــه واالســتعداد‬\n‫لألمــر بطهيــه قــام بوضــع عالمــات معينــه علــى تلــك الكراتــن وعنــد‬\n‫إشــرافه علــى موقــع آخــر وعودتــه وتفتيــش الثالجــة اتضــح لــه وجــود‬\n‫عــدد خمســة عشــر كرتــون دجــاج وخمســة كراتــن حلــم مفــروم مــن‬\n‫التــي قــام بوضــع العالمــة عليهــا مت إعادتهــا مــرة أخــرى إلــى الثالجــة‬\n‫مــن قبــل املدعــى عليهــم‪ .‬وبالتحقيــق مــع األول اعتــرف بقيامــه بإعــادة‬\n‫عــدد خمســة عشــر كرتــون دجــاج وعــدد خمســة كراتــن حلــم مفــروم‬\n‫للثالجــة بعــد اســتخراجها لطبخهــا للســجناء واســتلمها معــه مبســاعدة‬\n‫عضــو جلنــة اإلعاشــة والثانــي والثالــث لتوفيرهــا وطبخهــا بوجبــه اخــرى‬\n‫للســجناء وبالتحقيــق مــع الثانــي اعتــرف بقيامــه بإعــادة عــدد خمســة‬\n‫عشــر كرتــون دجــاج وعــدد خمســة كراتــن حلــم مفــروم مــن إعاشــة‬\n‫الســجناء بعــد صرفهــا واســتالمها مــن قبــل عضــو االعاشــة برفــق زميلــة‬\n                        ‫الثالــث والــذي أمــره بذلــك أمــن املســتودع األول ‪.‬‬\n‫وبالتحقيــق مــع الثالــث اعتــرف بقيامــه بإعــادة عــدد خمســة عشــر‬\n‫كرتــون دجــاج وعــدد خمســة كراتــن حلــم مفــروم مــن إعاشــة الســجناء‬\n‫بعــد صرفهــا واســتالمها مــن قبــل عضــو اإلعاشــة برفــق زميلــة األول‬\n‫والثانــي والــذي أمــره بذلــك أمــن املســتودع األول وانتهــى التحقيــق‬\n‫إلــى توجيــه االتهــام للمدعــى عليهــم بخيانــة األمانــة واالســتيالء علــى‬\n‫عــدد خمســة عشــر كرتــون دجــاج وعــدد خمســة كراتــن حلــم مفــروم‬\n‫مــن إعاشــة ســجناء إصالحيــة احلائــر وذلــك لألدلــة والقرائــن التاليــة‬\n                                                                              ‫‪:‬‬\n                       ‫‪ .1‬اعتراف األول ص (‪ )3‬من ملف التحقيق لفة (‪)2‬‬\n\n\n                                                                                  ‫‪70‬‬\n\f                            ‫‪ .2‬اعتراف الثاني ص (‪ )12‬من ملف التحقيق لفة (‪)3‬‬\n                           ‫‪ .3‬اعتراف الثالث ص (‪ )15‬من ملف التحقيق لفة (‪)3‬‬\n     ‫‪ .4‬محاضــر املواجهــة بينهــم وبــن عضــو جلنــة االعاشــة املدونــة علــى‬\n                                                             ‫صفحــة (‪ )8‬لفــة (‪)3‬‬\n                          ‫‪ .5‬احملضر املعد من قبل عضو االعاشة املرفق لفة (‪)7‬‬\n                                 ‫‪ .6‬شهادة الطباخ ‪ ... /‬املشار اليها املرفق لفة (‪)4‬‬\n     ‫وببحــث ســوابقهم اتضــح عــدم وجــود ســوابق مســجلة عليهــم حتــى‬\n                                                                            ‫تاريخــه ‪.‬‬\n     ‫وحيــث أن مــا أقدمــوا عليــه فعــل محــرم ومعاقــب عليــه شــرعا أطلــب‬\n     ‫إثبــات إدانتهــم مبــا أســند إليهــم واحلكــم عليهــم بعقوبــة تعزيريــة مشــددة‬\n     ‫تردعهــم وتزجــر غيرهــم (علمـ ًا بأنــه ال يوجد حق خــاص) ‪.‬وباهلل التوفيق‬\n     ‫‪ ،‬هــذه دعــواي وبســؤال املدعــى عليهــم بواســطة املترجــم املتعــاون لدينــا‬\n     ‫‪.....‬أجــاب املدعــى عليــه األول ‪.....‬قائــا كل مــا ذكــره املدعــي العــام‬\n     ‫يف دعــواه غيــر صحيــح والصحيــح بأننــي قــد أخرجــت اإلعاشــة املطلوبــة‬\n     ‫وقــد زاد منهــا خمســة عشــر كرتــون دجــاج وخمــس كراتني حلــم مفروم‬\n     ‫وأرجعتهــا جميعــا للثالجــة ولــم اســتولِ عليهــا هكــذا أجــاب وبســؤال‬\n     ‫املدعــى عليــه الثانــي والثالــث أجابــا جميعــا كل مــا ذكــره املدعــي‬\n     ‫العــام غيــر صحيــح والصحيــح بأننــا قــد أخرجنــا اإلعاشــة املطلوبــة وقــد‬\n     ‫زاد منهــا خمســة عشــر كرتــون دجــاج وخمــس كراتــن حلــم مفــروم‬\n     ‫وأرجعناهــا جميعــا للثالجــة ولــم نســتولي عليهــا هكــذا أجابــا هــذا‬\n     ‫كمــا جــرى االطــاع علــى املعاملــة علــى ملــف اســتكمال محاضــر لفــه‬\n     ‫رقــم ‪ 2‬وصحيفــة رقــم ‪ 3‬وهــو إقــرار مصــدق شــرعا للمدعــو ‪.....‬ونــص‬\n     ‫احلاجــة منــه (قمــت بأمــر ‪.....‬و‪ .....‬بإعــادة ‪ 15‬كرتــون دجــاج و‪ 5‬كراتــن‬\n\n\n‫‪71‬‬\n\f‫حلــم مفــروم للثالجــة ومت اكتشــافها مــن قبــل العســكري وليــس لــي‬\n‫فائــدة ســوى خــويف مــن أن يحصــل نقــص يف اإلعاشــة مســتقبال بصمتــه‬\n‫)اه ـ وبعــرض ذلــك علــى املدعــى عليــه األول ‪.....‬قــال كل مــا جــاء فيــه‬\n‫صحيــح هــذا كمــا جــرى االطــاع علــى ملــف اإلجــراءات لفــه رقــم ‪3‬‬\n‫وصحيفــة رقــم ‪ 15‬وهــو إقــرار للمدعــى عليه الثالــث ‪.....‬ونص احلاجة منه‬\n‫(لقــد طلــب منــي إعــادة خمســة عشــر كرتــون دجــاج وخمــس كراتــن‬\n‫حلــم مفــروم للثالجــة ) اه ـ وهــذا اإلقــرار مصــدق شــرعا وبعــرض ذلــك‬\n‫علــى املدعــى عليــه الثالــث ‪.....‬قــال كل مــا جــاء يف اإلقــرار صحيــح‬\n‫هكــذا قــرر هــذا كمــا جــرى االطــاع علــى نفــس امللــف وصحيفــة رقــم‬\n‫‪ 12‬وهــو إقــرار مصــدق شــرعا واملقــر هــو ‪.....‬ونــص احلاجــة منهــا (لقــد‬\n‫طلــب منــي إعــادة خمســة عشــر كرتــون دجــاج وخمــس كراتــن حلــم‬\n‫مفــروم وإعادتهــا للثالجة)اه ـ وبعــرض ذلــك علــى املدعــى عليــه الثانــي‬\n‫‪.....‬قــال كل مــا جــاء يف اإلقــرار صحيــح هكــذا قــرر وبعــرض ذلــك‬\n‫علــى املدعــي العــام قــال كل مــا ذكــروه غيــر صحيــح والصحيــح مــا‬\n‫جــاء يف دعــواي ولــدي شــاهد واطلــب املهلــة إلحضــاره هكــذا قــرر‬\n‫ثــم قــررا املدعــى عليهــم جميعــا كل مــا جــاء يف دعــوى املدعــي العــام‬\n‫صحيــح فقــد فعلنــا ذلــك الفعــل وانقصنــا خمســة عشــر كرتــون وخمــس‬\n‫كراتــن حلــم مفــروم مــن اجــل انــه يف الغــد تنــزل الشــركة الكميــة‬\n‫املطلوبــة وتنقــص منــه الكميــة التــي أحضرتهــا خمســة عشــر كرتــون‬\n‫دجــاج وخمــس كراتــن حلــم مفــروم وهــذا ينفــع الشــركة وقــد طلبــت‬\n‫منــا الشــركة ذلــك ونحــن تائبــون ونادمــون هكــذا قــرروا فبنــاء علــى‬\n                                               ‫مــا تقــدم مــن الدعــوى واإلجابــة‬\n‫وملصادقــة املدعــى عليهــم علــى دعــوى املدعــي العــام وال عــذر ملــن أقــر‬\n\n\n                                                                                      ‫‪72‬‬\n\f     ‫ومبــا أن هــذا الفعــل مشــن وخيانــة لألمانــة وقــد وصــف اهلل عــز وجــل‬\n     ‫املؤمنــن (والذيــن هــم ألماناتهــم وعهدهــم راعــون) وقــد قــال النبــي‬\n     ‫صلــى اهلل عليــه وســلم ( ال إميــان ملــن ال أمانــة لــه وال ديــن ملــن ال عهــد‬\n     ‫لــه ) أخرجــه احمــد مــن حديــث انــس رضــي اهلل عنــه كمــا أخرجــه‬\n     ‫ابــن أبــي شــيبه يف املصنــف والبيهقــي والبــزار وصححــه ابــن حبــان وقــد‬\n     ‫قــال النبــي صلــى اهلل عليــه وســلم (ال تســتقيم أمانــة رجــل حتــى يســتقيم‬\n     ‫لســانه وال يســتقيم لســانه حتــى يســتقيم قلبــه) اخرجــه احمــد وقــد‬\n     ‫قــال النبــي صلــى اهلل عليــه وســلم (اربــع إذا كــن فيــك فــا عليــك مــا‬\n     ‫فاتــك مــن الدنيــا صــدق احلديــث وحفــظ األمانــة وحســن اخللــق وعفــة‬\n     ‫املطعــم) أخرجــه احمــد والبخــاري واحلاكــم والبيهقــي فعليــه فقــد ثبــت‬\n     ‫لــدي ادانــة املدعــى عليهــم بخيانــة األمانــة واالســتيالء علــى عــدد خمســة‬\n     ‫عشــر كرتــون دجــاج وخمســة كراتــن حلــم مفــروم مــن إعاشــة ســجناء‬\n     ‫إصالحيــة احلائــر جلميــع ذلــك فقــد حكمــت بســجن املدعــى عليهــم‬\n     ‫الثالثــة ملــدة عشــرة اشــهر اعتبــارا مــن تاريــخ إيقافهــم ‪1434/04/10‬ه ـ‬\n     ‫وبجلدهــم مائتــي جلــده لــكل واحــد منهمــا مفرقــه علــى اربــع مــرات‬\n     ‫كل مــره خمســن جلــده بــن كل مــره واألخــرى ســبعة أيــام ويكــون‬\n     ‫منهــا مرتــن أمــام مقــر عملهــم الســابق ليكــون ذلــك عبــرة لآلخريــن‬\n     ‫وأوصــي بإبعادهــم جميعــا عــن هــذه البــاد وعــدم الســماح لهــم بالدخــول‬\n     ‫مــره أخــرى ســوى مــا يخــص نظــام احلــج والعمــرة بعــد اســتيفاء مالهــم ومــا‬\n     ‫عليهــم مــن حقــوق وبعرضــه عليهــم قنــع بــه املدعــى عليهــم امــا املدعــي‬\n     ‫العــام فقــرر اعتراضــه ويكتفــي بالالئحــة عــن الئحــة االعتــراض حــرر‬\n     ‫يف ‪1434/07/24‬ه ـ وصلــى اهلل وســلم علــى اشــرف األنبيــاء واملرســلني‪.‬‬\n     ‫احلمد هلل وحده وبعد‪ ،‬يف يوم الثالثاء املوافق‪1434/11/11‬هـ افتتحت‬\n\n\n‫‪73‬‬\n\f‫اجللســة الســاعة التاســعة والنصــف وفيهــا عــادت املعاملــة مــن محكمــة‬\n‫االســتئناف وبرفقهــا القــرار رقــم ‪ 34323910‬وتاريــخ ‪1434/9/22‬ه ـ‬\n‫الصــادر مــن الدائــرة اجلزائيــة الرابعــة ويتضمــن‪ ( :‬وبدراســة القــرار‬\n‫وصــورة ضبطــه وأوراق املعاملــة قــررت الدائــرة املصادقــة علــى احلكــم ‪.‬‬\n\n\n\n\n                                                                               ‫‪74‬‬\n\f75\n\f76\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"41499c81-d627-5952-8b7f-c01b2e788165","source_page_start":66,"source_page_end":76,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_down